window.LQ_SOL=window.LQ_SOL||{};window.LQ_SOL["2018年第九届"]={"2194":[{"aid":"108684","title":"蓝桥杯2018年第九届真题-递增三元组 简单二分","date":"2025-03-03","likes":2,"views":493,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-递增三元组\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include\"bits/stdc++.h\"\nusing namespace std;\n#define ll long long\nll n,a[100005],b[100005],c[100005],bx[100005];\nint main(){\n    cin>>n;\n    for(ll i=1;i<=n;i++)cin>>a[i];\n    for(ll i=1;i<=n;i++)cin>>b[i];\n    for(ll i=1;i<=n;i++)cin>>c[i];\n    sort(a+1,a+1+n);\n    sort(b+1,b+1+n);\n    sort(c+1,c+1+n);\n    ll t=0;\n    for(ll i=1;i<=n;i++){\n        ll k1=upper_bound(c+1,c+1+n,b[i])-c;\n        k1=n-k1+1;\n        bx[i]=k1;\n    }\n    for(ll i=1;i<=n;i++)bx[i]+=bx[i-1];\n    //for(ll i=1;i<=n;i++)cout<<b[i]<<' ';\n    //cout<<endl;\n    for(ll i=1;i<=n;i++){\n        ll k2=upper_bound(b+1,b+1+n,a[i])-b;\n        t+=bx[n]-bx[k2-1];\n    }\n    cout<<t<<endl;\n    return 0;\n}\n\n E 正文"},{"aid":"107690","title":"c++小白，暴力ac","date":"2024-12-03","likes":0,"views":511,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-递增三元组\n\n解题思路:\n\n注意事项:\n\n参考代码:\n//#include<iostream>\n//using namespace std;\n//int a[1000], b[1000], c[1000];\n//int main()\n//{\n//\tint n,num=0;\n//\tcin >> n;\n//\tfor (int i = 0; i < n; i++)\n//\t\tcin >> a[i];\n//\tfor (int i = 0; i < n; i++)\n//\t\tcin >> b[i];\n//\tfor (int i = 0; i < n; i++)\n//\t\tcin >> c[i];\n//\tfor (int i = 0; i < n; i++)\n//\t\tfor (int j = 0; j < n; j++)\n//\t\t\tfor (int k = 0; k < n; k++)\n//\t\t\t\tif (a[i] < b[j] && b[j] < c[k])num++;\n//\tcout << num;\n//\treturn 0;\n//}\n\n E 正文"},{"aid":"104195","title":"c++递增三元组  排序+二分","date":"2024-04-06","likes":0,"views":667,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-递增三元组\n\n解题思路:将 ai<bj<ck 拆成两个式子 bj>ai 和 bj<ck; 所以只需要枚举j即可再用二分找出边界\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\n#define int long long\nusing namespace std;\nconst int N =1e5+10;\nint n,a[N],b[N],c[N],ans;\nsigned main()\n{\n    ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);\n    cin>>n;\n    for(int i=1;i<=n;i++) cin>>a[i];\n    for(int i=1;i<=n;i++) cin>>b[i];\n    for(int i=1;i<=n;i++) cin>>c[i];\n    sort(a+1,a+1+n,less<int>());\n    sort(b+1,b+1+n,less<int>());\n    sort(c+1,c+1+n,less<int>());\n    for(int j=1;j<=n;j++){\n        //找出 ai<bj bj<ck 枚举b即可\n        //找出小于 b[j]的最大下标\n        int indexa=lower_bound(a+1,a+n+1,b[j])-a-1;//减1去除等于\n        //找出大于b[j]的最小下标\n        int indexc=upper_bound(c+1,c+n+1,b[j])-c;\n        indexc = n-indexc+1;\n        ans+=(indexa*indexc);\n    }\n    cout<<ans<<endl;\n    return 0;\n}\n\n E 正文"},{"aid":"103383","title":"java--study||O.o","date":"2024-03-13","likes":0,"views":671,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-递增三元组\n\n参考代码:\n\nimport java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.util.Arrays;\n\npublic class Main\n{   public static void main(String[] args) throws IOException\n    {   BufferedReader read = new BufferedReader(new InputStreamReader(System.in));//java数据较多时用这个输入，我还不太熟悉，可能写的不行\n        int n = Integer.parseInt(read.readLine().split(\" \")[0]);\n        int[] a = new int[n];\n        int[] b = new int[n];\n        int[] c = new int[n];\n        String[] in1 = read.readLine().split(\" \");\n        for(int i = 0; i < n; i++)\n            a[i] = Integer.parseInt(in1[i]);\n        String[] in2 = read.readLine().split(\" \");\n        for(int i = 0; i < n; i++)\n            b[i] = Integer.parseInt(in2[i]);\n        String[] in3 = read.readLine().split(\" \");\n        for(int i = 0; i < n; i++)\n            c[i] = Integer.parseInt(in3[i]);\n\n        Arrays.sort(a);\n        Arrays.sort(b);\n        Arrays.sort(c);\n        long res = 0;\n        int p = 0;\n        int q = 0;\n        for(int i = 0; i < n; i++)//枚举b数组的值\n        {   while(p < n && a[p] < b[i])\n                p++;\n            while(q < n && c[q] <= b[i])\n                q++;\n            res += (long)p * (n - q);\n        }\n        System.out.print(res);\n    }\n}\n\n E 正文"},{"aid":"103223","title":"蓝桥杯2018年第九届真题-递增三元组","date":"2024-03-09","likes":0,"views":765,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-递增三元组\n\n做法1：暴力枚举\n\n首先考虑暴力做法，三个数组嵌套枚举，O(n3)的时间复杂度\n#include <iostream>\n#include <cstring>\n#include <cstdio>\n#include <algorithm>\n\nusing namespace std;\nusing ll=long long;\n\nconst int N=1e5+10;\n\nint a[N],b[N],c[N];\nint main()\n{\n  ios::sync_with_stdio(0),cin.tie(0),cout.tie(0);\n  int n;cin>>n;\n  int res=0;\n  for(int i=1;i<=n;i++)cin>>a[i];\n  for(int i=1;i<=n;i++)cin>>b[i];\n  for(int i=1;i<=n;i++)cin>>c[i];\n  for(int i=1;i<=n;i++)\n  {\n    for(int j=1;j<=n;j++)\n    {\n      for(int k=1;k<=n;k++)\n      {\n        if(a[i]<b[j]&&b[j]<c[k])\n        res++;\n      }\n    }\n  }\n  cout<<res;\n  return 0;\n}尝试通过枚举的次序进行优化本题，先枚举B数组，在A中寻找小于B[i]的数的个数cnt1，在C中寻找大于B[i]的数的个数cnt2，带有B[i]的合法选择数就是cnt1*cnt2。\n//前缀和优化\n#include <iostream>\n#include <string.h>\nusing namespace std;\nconst int N=100005;\nint n,a[N],b[N],c[N];\nint cnt=0;\nint num[N],s[N];\nint as[N],cs[N];\nint main(){\n    cin>>n;//输入\n    for(int i=0;i<n;i++) cin>>a[i];\n    for(int i=0;i<n;i++) cin>>b[i];\n    for(int i=0;i<n;i++) cin>>c[i];\n    //处理as\n    for(int i=0;i<n;i++) num[a[i]]++;//  记录a[i]出现的次数\n\n    for(int i=0;i<=N;i++) s[i]=s[i-1]+num[i];// 递推求得关于a[i]的所有前缀和s[i]\n\n    for(int i=0;i<n;i++) as[i]=s[b[i]-1];// as代表比b[i]小的数的前缀和\n    //还原数组\n    memset(num,0,sizeof(num));\n    memset(s,0,sizeof(s));\n\n    //处理cs\n    for(int i=0;i<n;i++) num[c[i]]++;//  记录c[i]出现的次数\n\n    for(int i=0;i<=N;i++) s[i]=s[i-1]+num[i];//  递推求得关于c[i]的所有前缀和s[i]\n\n    for(int i=0;i<n;i++) cs[i]=s[N]-s[b[i]];//  cs代表比b[i]大的数的前缀和；\n    //注意不能是s[N-b[i]],这样求得的是从0到N-b[i]的前缀和，不是b[i]到N的前缀和\n\n    //求结果\n    long long res=0;//  数据量较大，用long long\n    for(int i=0;i<n;i++)\n    res+=(long long)as[i]*cs[i];\n    cout<<res<<endl;\n    return 0;\n}\n\n E 正文"}],"2274":[{"aid":"103426","title":"java--study||O.o","date":"2024-03-14","likes":0,"views":635,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-航班时间\n\n参考代码:\n\nimport java.text.ParseException;\nimport java.text.SimpleDateFormat;\nimport java.util.Date;\nimport java.util.Scanner;\n\npublic class Main\n{   static Scanner scanner = new Scanner(System.in);\n    public static void main(String[] args) throws ParseException//日期时间格式的抛异常\n    {   int n = scanner.nextInt();\n        scanner.nextLine();\n        while(n-- > 0)\n        {   int to = getTime();\n            int back = getTime();\n            int res = (to + back) / 2;//飞去的时间时是：飞行时间-时差，回来的时间是：飞行时间+时差\n            System.out.printf(\"%02d:%02d:%02d\\n\", res / 3600, res / 60 % 60, res % 60); //printf前置0，防空位\n        }\n    }\n    static int getTime() throws ParseException\n    {   String[] in = scanner.nextLine().split(\" \");\n        SimpleDateFormat format = new SimpleDateFormat(\"HH:mm:ss\");//format类的自定义时间格式匹配\n        Date start = format.parse(in[0]);\n        Date end = format.parse(in[1]);\n        int t = 0;\n        if(in.length > 2)\n            t = Integer.parseInt(in[2].substring(2, 3));\n        return (int) ((end.getTime() - start.getTime()) / 1000 + t * 24 * 3600);//Date类返回的是纳秒\n    }\n}\n\n E 正文"},{"aid":"95190","title":"蓝桥杯2018年第九届真题-航班时间-JAVA解法-简单易懂","date":"2023-03-23","likes":0,"views":856,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-航班时间\n\n Server-side output Markdown text\n由题意得到飞机的飞行时间是来回**两趟飞行的起飞和降落时间差的平均值**\n在Java中**Calendar类有add方法能实现对日期的增减**，这里就用Calendar对日期进行处理\n将输入进来的时间转为Calendar类，输入中有（+n）字样的就对该对象通过add方法进行对其日期+n，**分别拿到起飞及降落对应日期的时间戳，做差得到起飞及降落的时间差（ms），即为该趟飞行时间(ms)**\n再对两趟飞行都求得飞行时间，取平均值，再转化为HH\\:mm\\:ss的形式即可\n\n``\n\n    import java.util.Arrays;\n    import java.util.Calendar;\n    import java.util.Scanner;\n\n    public class Main {\n\n    \tpublic static void main(String[] args) {\n    \t\tScanner sc = new Scanner(System.in);\n    \t\tint n = sc.nextInt();\n    \t\tsc.nextLine(); // 将数字后的回车吃掉\n    \t\twhile(n>0) { //输入n组数据\n    \t\t\tn--;\n    \t\t\tString[] s1 = sc.nextLine().split(\" \"); //第一趟的时间\n    \t\t\tString[] s2 = sc.nextLine().split(\" \"); //第二趟的时间\n    \t\t\tlong l1 = subtime(s1); // 求得第一趟的飞行时间(ms)\n    \t\t\tlong l2 = subtime(s2); //求得第二趟的飞行时间(ms)\n    \t\t\tlong l = (l2+l1)/2;\n\t\t\t\t// 对平均飞行时间处理输出\n    \t\t\tl/=1000;\n    \t\t\tint h = (int)l/3600;\n    \t\t\tint m = (int)(l%3600)/60;\n    \t\t\tint s = (int)l-h*3600-m*60;\n    \t\t\tSystem.out.printf(\"%02d:%02d:%02d\\n\",h,m,s);\n    \t\t}\n    \t}\n    \tpublic static long subtime(String[] s) {\n    \t\tString[] start = s[0].trim().split(\":\"); // 起飞时间\n    \t\tString[] end = s[1].trim().split(\":\"); // 降落时间\n    \t\tCalendar c1 = Calendar.getInstance(); //\n    \t\tc1.set(2023,3,23,Integer.parseInt(start[0]),Integer.parseInt(start[1]),Integer.parseInt(start[2])); // 对起飞时间创建日历对象【年月日随便设，只要和降落的统一即可】\n    \t\tCalendar c2 = Calendar.getInstance();\n    \t\tc2.set(2023,3,23,Integer.parseInt(end[0]),Integer.parseInt(end[1]),Integer.parseInt(end[2]));// 对降落时间创建日历对象\n    \t\tif(s.length==3) { // 如果输入中含(+n)\n    \t\t\tc2.add(Calendar.DATE, s[2].trim().charAt(2)-'0'); // 对日期增加指定天数\n    \t\t}\n    \t\treturn c2.getTimeInMillis()-c1.getTimeInMillis(); // 返回飞行时间对应的毫秒数\n    \t}\n\n    }\n    ``\n\n E 正文"},{"aid":"94797","title":"蓝桥杯2018年第九届真题-航班时间-暴力解法","date":"2023-03-13","likes":0,"views":687,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-航班时间\n\n解题思路:\n\n注意事项:\n\n参考代码:\nimport re\nn=int(input())\nls=[]\nwhile n!=0:\n    a=list(map(str,input().split()))\n    b=list(map(str,input().split()))\n    if len(a)==2:\n        time_first=a[0].split(':')\n        time_end=a[1].split(':')\n        hour=int(time_end[0])-int(time_first[0])\n        if int(time_end[1])<int(time_first[1]):\n            minute = (60+int(time_end[1])) - int(time_first[1])\n            hour-=1\n        else:\n            minute=int(time_end[1])-int(time_first[1])\n        if int(time_end[2])<int(time_first[2]):\n            ss=(60+int(time_end[2]))-int(time_first[2])\n            minute-=1\n        else:\n            ss = int(time_end[2]) - int(time_first[2])\n    else:\n        time_first = a[0].split(':')\n        time_end = a[1].split(':')\n        day=int(re.findall('\\d+',a[2])[0])\n        hour = int(time_end[0]) + (24*day-int(time_first[0]))\n        if int(time_end[1]) < int(time_first[1]):\n            minute = (60 + int(time_end[1])) - int(time_first[1])\n            hour -= 1\n        else:\n            minute = int(time_end[1]) - int(time_first[1])\n        if int(time_end[2]) < int(time_first[2]):\n            ss = (60 + int(time_end[2])) - int(time_first[2])\n            minute -= 1\n        else:\n            ss = int(time_end[2]) - int(time_first[2])\n    if len(b)==2:\n        time_first = b[0].split(':')\n        time_end = b[1].split(':')\n        hour_b = int(time_end[0]) - int(time_first[0])\n        if int(time_end[1]) < int(time_first[1]):\n            minute_b = (60 + int(time_end[1])) - int(time_first[1])\n            hour_b -= 1\n        else:\n            minute_b = int(time_end[1]) - int(time_first[1])\n        if int(time_end[2]) < int(time_first[2]):\n            ss_b = (60 + int(time_end[2])) - int(time_first[2])\n            minute_b -= 1\n        else:\n            ss_b= int(time_end[2]) - int(time_first[2])\n    else:\n        time_first = b[0].split(':')\n        time_end = b[1].split(':')\n        day=int(re.findall('\\d+',b[2])[0])\n        hour_b = int(time_end[0]) + (24*day-int(time_first[0]))\n        if int(time_end[1]) < int(time_first[1]):\n            minute_b = (60 + int(time_end[1])) - int(time_first[1])\n            hour_b -= 1\n        else:\n            minute_b = int(time_end[1]) - int(time_first[1])\n        if int(time_end[2]) < int(time_first[2]):\n            ss_b = (60 + int(time_end[2])) - int(time_first[2])\n            minute_b -= 1\n        else:\n            ss_b = int(time_end[2]) - int(time_first[2])\n    h=str((hour+hour_b)//2)\n    m=str((minute+minute_b)//2)\n    s=str((ss+ss_b)//2)\n    if len(h)==1:\n        h='0'+h\n    if len(m)==1:\n        m='0'+m\n    if len(s)==1:\n        s='0'+s\n    time=h+':'+m+':'+s\n    ls.append(time)\n    n-=1\nfor i in ls:\n    print(i)\n\n E 正文"},{"aid":"94644","title":"================================================================","date":"2023-03-08","likes":0,"views":658,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-航班时间\n\n参考代码:\n#include <stdio.h>\n#include <string.h>\nint function(char str[])\n{\n    int h1,m1,s1,h2,m2,s2,t=0;\n    if(strlen(str)>17)\n        sscanf(str,\"%d:%d:%d %d:%d:%d (+%d)\", &h1,&m1,&s1,&h2,&m2,&s2,&t);\n    else\n        sscanf(str,\"%d:%d:%d %d:%d:%d\",&h1,&m1,&s1,&h2,&m2,&s2);\n    return  t*24*60*60+h2*60*60+m2*60+s2-h1*60*60-m1*60-s1;\n}\n\nint main()\n{\n    int n,i,t1,t2,h,m,s,t;\n    char str[100];\n    scanf(\"%d\\n\",&n);\n    for(i=0;i<n;i++)\n    {\n        gets(str);\n        t1=function(str);\n        gets(str);\n        t2=function(str);\n        t=(t1+t2)/2;\n        h=t/3600;\n        m=t/60%60;\n        s=t%60;\n        printf(\"%02d:%02d:%02d\\n\",h,m,s);\n    }\n    scanf(\"%d\",&n);\n    return 0;\n}\n\n E 正文"},{"aid":"85525","title":"蓝桥杯2018年第九届真题-航班时间python解法","date":"2022-03-20","likes":0,"views":999,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-航班时间\n\n Server-side output Markdown text\n    import datetime\n    n = int(input())\n    ans = [] #存答案\n    li = [] #用来存所有飞行时间\n    for i in range(n*2): #一共要输入n*2行\n            s = list(input().split()) #输入一行\n            if len(s)>2: #如果有(+1)或(+2) #设置天数间隔\n                    if s[2][2]=='1':\n                            dt1 = datetime.datetime.strptime('10 '+s[0],'%d %H:%M:%S')\n                            dt2 = datetime.datetime.strptime('11 '+s[1],'%d %H:%M:%S')\n                    elif s[2][2]=='2':\n                            dt1 = datetime.datetime.strptime('10 '+s[0],'%d %H:%M:%S')\n                            dt2 = datetime.datetime.strptime('12 '+s[1],'%d %H:%M:%S')\n            else: #否则不设置\n                    dt1 = datetime.datetime.strptime(s[0],'%H:%M:%S')\n                    dt2 = datetime.datetime.strptime(s[1],'%H:%M:%S')\n            td1 = dt2 - dt1 #计算时间差\n            li.append((td1.seconds+(td1.days)*24*3600)) #记住这里还要加上天数差的时间！！\n\n    i=0\n    while i<len(li):\n            an = (li[i]+li[i+1])//2 #实际飞行时间为来回飞行时间的平均值\n            i+=2\n            ans.append(an) #存入答案\n\n    for j in range(n):\n            h = ans[j]//3600      #时\n            m = (ans[j]%3600)//60 #分\n            s = ans[j]-h*3600-m*60 #秒\n            print('{:02d}:{:02d}:{:02d}'.format(int(h),int(m),int(s))) #输出结果\n\n E 正文"}],"2275":[{"aid":"79632","title":"蓝桥杯2018年第九届真题-三体攻击 题解","date":"2021-08-09","likes":1,"views":1843,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-三体攻击\n\n解题思路:有手就行\n\n注意事项：不要超时\n![](https://blog.dotcpp.com/uploads/20210809/1628461442593570.jpeg)\n参考代码:\n#pragma GCC optimize(2)\n#include<bits/stdc++.h>\nusing namespace std;\ntypedef long long LL;\nconst int INF = 0x3f3f3f3f;\nconst double Pi = acos(-1);\nnamespace {\n  template <typename T> inline void read(T &x) {\n    x = 0; T f = 1;char s = getchar();\n    for(; !isdigit(s); s = getchar()) if(s == '-') f = -1;\n    for(;  isdigit(s); s = getchar()) x = (x << 3) + (x << 1) + (s ^ 48);\n    x *= f;\n  }\n}\n#define fio ios::sync_with_stdio(false);cin.tie(0);cout.tie(0);\n#define _for(n,m,i) for (register int i = (n); i <  (m); ++i)\n#define _rep(n,m,i) for (register int i = (n); i <= (m); ++i)\n#define _srep(n,m,i)for (register int i = (n); i >= (m); i--)\n#define _sfor(n,m,i)for (register int i = (n); i >  (m); i--)\n#define lson rt << 1, l, mid\n#define rson rt << 1 | 1, mid + 1, r\n#define lowbit(x) x & (-x)\n#define pii pair<int,int>\n#define fi first\n#define se second\nconst int N = 2e6+5;\nstruct node {\n  int la, ra, lb, rb, lc, rc;\n  LL  h;\n  void get() {\n    read(la); read(ra);read(lb); read(rb);read(lc); read(rc); read(h);\n  }\n}op[N];\nLL a[N], b[N];\nint A, B, C, m;\ninline int get(int i, int j, int k) {\n  return ((i-1) * B + j - 1) * C + k;\n}\nvoid ready(int n) {\n  b[get(op[n].la, op[n].lb, op[n].lc)] += op[n].h;\n  b[get(op[n].ra+1, op[n].lb, op[n].lc)] -= op[n].h;\n  b[get(op[n].la, op[n].rb+1, op[n].lc)] -= op[n].h;\n  b[get(op[n].la, op[n].lb, op[n].rc+1)] -= op[n].h;\n\n  b[get(op[n].ra+1, op[n].rb+1, op[n].rc+1)] -= op[n].h;\n  b[get(op[n].la, op[n].rb+1, op[n].rc+1)] += op[n].h;\n  b[get(op[n].ra+1, op[n].lb, op[n].rc+1)] += op[n].h;\n  b[get(op[n].ra+1, op[n].rb+1, op[n].lc)] += op[n].h;\n}\nbool judge(int m) {\n  memset(b, 0, sizeof b);\n  _rep(1, m, i) ready(i);\n  _rep(1, A*B*C, l) {\n    b[l] -= b[l-B*C-C];//b[get(i-1, j-1, k)];\n    b[l] -= b[l-B*C-1];//b[get(i-1, j, k-1)];\n    b[l] -= b[l-C-1]; //b[get(i, j-1, k-1)];\n\n    b[l] += b[l-B*C];//b[get(i-1, j, k)];\n    b[l] += b[l-C];//b[get(i, j-1, k)];\n    b[l] += b[l-1];//b[get(i, j, k-1)];\n    b[l] += b[l-B*C-C-1];//b[get(i-1, j-1, k-1)];\n    if(b[l] > a[l]) return 1;\n  }\n  return 0;\n}\nint main() {\n  read(A); read(B); read(C); read(m);\n  _rep(1, A*B*C, i) read(a[i]);\n  _rep(1, m, i) op[i].get();\n  int l = 1, r = m, ans;\n  judge(1);\n  while(l <= r) {\n    int mid = l + r >> 1;\n    if(judge(mid)) {\n      ans = mid; r = mid-1;\n    } else l = mid + 1;\n  }\n  cout << ans;\n}\n\n E 正文"}],"2276":[{"aid":"95697","title":"蓝桥杯2018年第九届真题-全球变暖","date":"2023-04-06","likes":0,"views":793,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-全球变暖\n\n解题思路:\n\n注意事项:\n\n参考代码:\nfrom collections import deque\nn=int(input())\nm=[[i for i in input()]for _ in range(n)]\nv=[[0 for _ in range(n)] for _ in range(n)]\ndir=[[1,0],[-1,0],[0,1],[0,-1]]\nflag=True\ndef bfs(x,y):\n    q=deque([(x,y)])\n    global flag\n    while q:\n        x,y=q.popleft()\n        if m[x+1][y]=='#' and m[x-1][y]=='#' and m[x][y+1]=='#' and m[x][y-1]=='#':\n            flag=False\n        for i in range(4):\n            nx=x+dir[i][0]\n            ny=y+dir[i][1]\n            if 0<=nx<n and 0<=ny<n and m[nx][ny]==\"#\" and v[nx][ny]==0:\n                v[nx][ny]=1\n                q.append((nx,ny))\nans=0\nfor i in range(n):\n    for j in range(n):\n        if m[i][j]=='#'and v[i][j]==0:\n            v[i][j]=1\n            flag=True\n            bfs(i,j)\n            if flag==True:\n                ans+=1\nprint(ans)\n\n E 正文"},{"aid":"95186","title":"蓝桥杯2018年第九届真题-全球变暖-JAVA【参考优质题解】-详细注释","date":"2023-03-23","likes":0,"views":919,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-全球变暖\n\n Server-side output Markdown text\n定义静态全局变量：\nvisited数组标记当前点是否被访问；\nmap表示地图；\ndx，dy分别表示x，y进行上下左右偏移时的偏移量。\n\n用BFS思想解题：\n对**地图上每个未访问过的表示陆地的点【表示一个岛屿】进行bfs**，记录沉没的岛屿数；\n在bfs中，每访问一个表示陆地的点就将其标记未已经访问，对该点上下左右四个方向查找陆地，将该岛屿整块进行标记，避免后续遍历时重复访问岛屿，在四个方向上查找陆地过程中记录当前点是否**四个方向都是陆地**，如果是，说明该岛屿不会完全沉没，返回0，如果遍历完整个岛屿都不存在**这样的点**，说明当前岛屿会完全沉没，返回1【完全沉没岛屿数+1】。\n\n\timport java.util.ArrayDeque;\n    import java.util.Queue;\n    import java.util.Scanner;\n\n    public class Main {\n    \tstatic boolean[][] visited = new boolean[1010][1010];\n    \tstatic int[] dx = {-1,1,0,0};\n    \tstatic int[] dy = {0,0,-1,1};\n    \tstatic char[][] map = new char[1010][1010];\n    \tpublic static void main(String[] args) {\n    \t\tScanner sc = new Scanner(System.in);\n    \t\tint n = sc.nextInt();\n    \t\tsc.nextLine();\n    \t\tString temp;\n    \t\tfor(int i=0;i<n;i++) {\n    \t\t\ttemp = sc.nextLine();\n    \t\t\tmap[i] = temp.toCharArray();\n    \t\t}\n    \t\tint res = 0; // 记录结果【沉没岛屿数】\n    \t\tfor(int i=0;i<n;i++) {\n    \t\t\tfor(int j=0;j<n;j++) {\n    \t\t\t\tif(map[i][j]=='#'&&!visited[i][j]) { // 当前点为陆地且未被访问\n\t\t\t\t\t\tvisited[i][j] = true; // 将其标记为已访问\n    \t\t\t\t\tres+=dfs(i,j); //记录结果\n    \t\t\t\t}\n    \t\t\t}\n    \t\t}\n    \t\tSystem.out.println(res);\n\n    \t}\n\t\t// x,y表示当前要访问点的下标\n    \tpublic static int dfs(int x,int y) {\n    \t\tQueue<int[]> queue = new ArrayDeque<>(); // 用来装当前岛屿的点，进行逐个访问\n    \t\tint flag = 1; //标记该岛屿是否会被完全淹没【是否存在四周都是陆地的陆地】，默认会被完全淹没\n\n\t\t\t // wx,wy保存队列中弹出点的坐标；\n\t\t\t //tx,ty保存该点在四个方向偏移的坐标；\n\t\t\t //k用来记录该点四面中是陆地的数量\n    \t\tint k = 0,tx ,ty ,wx,wy;\n    \t\tint[] temp = null; // 保存队列中的弹出结点\n    \t\tqueue.offer(new int[]{x,y}); // 先将当前要访问的结点入队\n\t\t\t// 遍历访问包含该点的整个岛屿【避免后续重复遍历】\n    \t\twhile(!queue.isEmpty()) {\n    \t\t\ttemp = queue.poll();\n    \t\t\twx = temp[0];wy = temp[1];\n    \t\t\tk = 0;\n\t\t\t\t// 看上下左右是否存在陆地\n    \t\t\tfor(int i=0;i<4;i++) {\n    \t\t\t\ttx =wx+dx[i];\n    \t\t\t\tty =wy+dy[i];\n    \t\t\t\tif(map[tx][ty]=='#') {\n    \t\t\t\t\tk++;\n    \t\t\t\t\tif(!visited[tx][ty]) { // 如果该点未访问\n    \t\t\t\t\t\tvisited[tx][ty] = true;\n    \t\t\t\t\t\tqueue.offer(new int[] {tx,ty}); // 入队\n    \t\t\t\t\t}\n    \t\t\t\t}\n    \t\t\t}\n    \t\t\tif(k==4) flag = 0; //说明至少存在四面都是陆地的点，该岛屿不会被完全淹没\n    \t\t}\n    \t\treturn flag;\n    \t}\n\n    }\n\n E 正文"},{"aid":"95149","title":"蓝桥杯2018年第九届真题-全球变暖(BFS)","date":"2023-03-22","likes":0,"views":948,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-全球变暖\n\n Server-side output Markdown text\n####解题思路\nBFS每次遍历一座小岛，统计小岛的陆地数量（tot），以及被水淹没的陆地数量（bou），判断小岛陆地数量与被水淹没的陆地数量是否相等（tot == bou），若是相等则小岛被淹没。\n\n####参考代码\n```cpp\n#include <iostream>\n#include <cstring>\n#include <algorithm>\n#include <queue>\n#define x first\n#define y second\n\nusing namespace std;\n\ntypedef pair<int, int> PII;\nconst int N = 1010;\nchar g[N][N];\nbool st[N][N];\nint n;\nint dx[] = {-1, 0, 1, 0}, dy[] = {0, 1, 0, -1};\n\nbool bfs(int a, int b)\n{\n    queue<PII> q;\n    q.push({a, b});\n    st[a][b] = true;\n\n    int tot = 0, bou = 0; // 陆地数量， 被淹陆地数量\n    while (q.size())\n    {\n        auto t = q.front();\n        tot ++ ; // 因为入队的都是陆地，直接记录小道陆地数量\n        q.pop();\n\n        bool flag = false; // 标记该陆地是否被淹\n        for (int i = 0; i < 4; i ++ )\n        {\n            int X = t.x + dx[i], Y = t.y + dy[i];\n            if (!st[X][Y] && 0 <= X && X < n && 0 <= Y && Y < n)\n            {\n                if (g[X][Y] == '#') // 若是遍历为陆地则入队\n                {\n                    st[X][Y] = true;\n                    q.push({X, Y});\n                }\n                if (g[X][Y] == '.') // 若是陆地上下左右方向为水，则标记为被淹\n                {\n                    flag = true;\n                }\n            }\n        }\n\n        if (flag) bou ++ ; // 被淹陆地 +1 。\n\n    }\n\n    return tot == bou;\n}\n\nint main()\n{\n    cin >> n;\n    for (int i = 0; i < n; i ++ )\n            scanf(\"%s\", &g[i]);\n\n    int ans = 0;\n    for (int i = 0; i < n; i ++ )\n        for (int j = 0; j < n; j ++ )\n            if (g[i][j] == '#' && !st[i][j]) // 每次遍历一座小岛，st记录陆地是否被遍历。\n                if (bfs(i, j)) ans ++ ; // 若是 tot == bou 则小岛被淹\n\n    cout << ans;\n\n    return 0;\n}\n```\n\n E 正文"},{"aid":"88812","title":"2276: 蓝桥杯2018年第九届真题-全球变暖（bfs）","date":"2022-07-18","likes":0,"views":1586,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-全球变暖\n\n解题思路:\n做这道题看错了两个地方，一开始做成了求存活的#的数量，后来又看成了存活的岛屿的数量，其实题目问的是有多少岛屿被淹没。\n可以上下左右联通的为同一岛屿，以样例数据为例：\n![](https://blog.dotcpp.com/uploads/20220718/1658127621328235.png)\n有两岛屿，只有右下角的岛屿中有一个不和海洋接触的陆地#，所以左上角的岛屿会被淹没，右下角的岛屿会存留下来。\n所以问题转变成了将这些岛屿找出来，并且查找岛屿内有没有不和海洋连接的陆地，如果没有的就看成被淹没，答案数量+1。\n先遍历数组，如果找到了陆地#，而且没有被标记过（不是之前岛屿里的陆地），就从这个陆地开始向上下左右四个方向寻找，将找到陆地进行标记，在下一次寻找的时候不查找标记过的陆地#。\n同时记录一个陆地上下左右是不是都是陆地，如果找遍联通的陆地都没有（说明这个岛屿会被淹没），就返回一个0，让答案数+1。\n上面的情况用dfs bfs都可以做，不过bfs在做判断上更简单一些。\n\n参考代码:\n#include <bits/stdc++.h>\n#include <queue>\nusing namespace std;\n\nstruct node{\n\tint x,y,l;//坐标xy，l记录走过的步数，不过在这道题里没有用\n};\n\nint dx[8]={1,-1,0,0,-1,1,1,-1};//上 下 左 右 右上 右下 左下 左上\nint dy[8]={0,0,-1,1,1,1,-1,-1};//四个方向寻找就可以了\n\nbool vis[1001][1001];//记录是否访问过\nchar p[1001][1001];\nqueue<node>q;\nint n,z=0;\n\nbool dfs(int x1,int y1){\n\tbool b=0;\n\tq.push({x1,y1,1});//坐标入队，从x1 y1开始寻找\n\twhile(!q.empty()){\n\t\tint k=0;//记录周围有多少个陆地\n\t\tnode now=q.front();\n\t\tvis[now.x][now.y]=1;\n\t\tq.pop();\n\t\tfor(int i=0;i<4;i++){//四个方向寻找\n\t\t\tint x=now.x+dx[i];\n\t\t\tint y=now.y+dy[i];\n\t\t\tif(x>0&&y>0&&x<=n&&y<=n){\n\t\t\t\tif(p[x][y]=='#'){//如果是陆地\n\t\t\t\t\tk++;\n\t\t\t\t\tif(!vis[x][y]){//如果没有访问过\n\t\t\t\t\t\tvis[x][y]=1;\n\t\t\t\t\t\tq.push({x,y,now.l+1});\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif(k==4)b=1;//如果上下左右都是陆地\n\t}\n\treturn b;//返回岛屿是否没有被淹没\n\n}\n\nint main()\n{\n\tcin>>n;\n\tfor(int i=1;i<=n;i++){\n\t\tfor(int j=1;j<=n;j++){\n\t\t\tcin>>p[i][j];\n\t\t}\n\t}\n\tfor(int i=1;i<=n;i++){\n\t\tfor(int j=1;j<=n;j++){\n\t\t\tif(vis[i][j]==0&&p[i][j]=='#'){//如果没有访问过并且是陆地\n\t\t\t\tif(!dfs(i,j))z++;//如果这个岛屿会被淹没，答案+1\n\t\t\t}\n\t\t}\n\t}\n\n\tcout<<z;\n\n \treturn 0;\n}\n\n E 正文"},{"aid":"86505","title":"【2018 蓝桥杯】全球变暖【BFS】【Python解法】","date":"2022-04-08","likes":0,"views":1188,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-全球变暖\n\n Server-side output Markdown text\n思路很清晰。\n\n1. 遍历图中所有的点，遇到 “#”， 代表是岛屿的区块。\n2. 用 bfs 向外扩展岛屿，遇到海就停住。 （使用一个 vis 记录遍历过的点）\n3. 在遍历一个岛屿的过程中，同时记录不会被淹没区块的数量：实现一个 flood 函数判断区块的上下左右是否是海洋。\n4. bfs 返回剩余区块的数量。 返回若为零代表完全被淹没。\n\n几个注意的点：\n1. 题目问的是被完全淹没的点的数量。我看成了剩余的岛屿的数量，结果因为给的样例两种情况都是一就弄错了。\n2. 注意需要单独判断一下起始点是否会被淹没来决定区块数量的初始化值。（也可以不标记在后续的点中被搜索到。）\n\n```python\nimport sys\nfrom collections import deque\n\ninput = sys.stdin.readline\n\nn = int(input())\nsea = [list(input().strip()) for _ in range(n)]\n\ndirect = [(0, 1), (1, 0), (-1, 0), (0, -1)]\nvis = [[False]*n for _ in range(n)]\n\ndef check(x, y):\n    if (x<0 or y<0 or x>=n or y>=n): return False\n    if (vis[x][y]): return False\n    if (sea[x][y]==\".\"): return False\n    return True\ndef flood(x, y):\n    for dx, dy in direct:\n        nx, ny = x + dx, y + dy\n        if (nx<0 or ny<0 or nx>=n or ny>=n): continue\n        if(sea[nx][ny]==\".\"): return True\n    return False\ndef bfs(x ,y):\n    q = deque()\n    q.append((x, y))\n    blocks = 0 if flood(x, y) else 1\n    while q:\n        tx, ty = q.popleft()\n        for dx, dy in direct:\n            nx, ny = tx + dx, ty + dy\n            if(check(nx, ny)):\n                vis[nx][ny] = True\n                q.append((nx, ny))\n                if(not flood(nx, ny)): blocks+=1\n    return blocks\nres = 0\nfor x in range(n):\n    for y in range(n):\n        if(sea[x][y]==\"#\" and not vis[x][y]):\n            vis[x][y] = True\n            rest = bfs(x, y)\n            if(rest==0): res+=1\nprint(res)\n```\n\n E 正文"}],"2277":[{"aid":"102772","title":"蓝桥杯2018年第九届真题-倍数问题（滚动数组）","date":"2024-02-19","likes":0,"views":776,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-倍数问题\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<iostream>\n#include<algorithm>\n#include<cstring>\n#include<cmath>\n#include<vector>\nusing namespace std;\n#define LL long long\n\nconst int N=1e5+9;\nint n,k;\nint f[4][N],g[4][N];//滚动数组\nvector <int> a[N];\n\nint main()\n{\n    cin>>n>>k;\n    for(int i=1;i<=n;i++)\n    {\n        int x;\n        cin>>x;\n        a[x%k].push_back(x);\n    }\n    memset(f,-1,sizeof(f));\n    memset(g,-1,sizeof(g));\n    for(int i=0;i<k;i++)\n    {\n        if(a[i].size()==0)\n            continue;//没有对应的余数就跳过\n        sort(a[i].begin(),a[i].end());\n        reverse(a[i].begin(),a[i].end());\n        int len=a[i].size();\n        //取余数相同的比较大的几个（3个）\n        for(int j=0;j<min(3,len);j++)\n        {\n            int x=a[i][j];//可能会选到的数x;\n            g[1][i]=max(f[1][i],x);\n            for(int p=1;p<=2;p++)//枚举数的个数逐渐增加时，最大的和\n            {\n                for(int v=0;v<k;v++)\n                {\n                    if(f[p][v]!=-1)\n                        g[p+1][(v+x)%k]=max(g[p+1][(v+x)%k],f[p][v]+x);\n                }\n            }\n            for(int p=1;p<=3;p++)\n            {\n                for(int v=0;v<k;v++)\n                {\n                    f[p][v]=g[p][v];//复制回f数组\n                }\n            }\n        }\n    }\n    cout<<g[3][0];\n    return 0;\n}\n\n E 正文"},{"aid":"98098","title":"蓝桥杯2018年第九届真题-倍数问题(模运算)","date":"2023-08-19","likes":0,"views":786,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-倍数问题\n\n解题思路:\n首先对输入排序，枚举两个余数，可以算出第三个余数，由于三个余数和在0到3(k-1),故合法的只为0,k,2k,算出这三个可能的情况，判断是否存在即可。\n注意事项:\n对n,k枚举可能超时，复杂度O(k^2)，选择一个余数时选择最大的数字，所以要先排序。\n参考代码:\n\n#include<bits/stdc++.h>\nusing namespace std;\n#define maxx 1100\nint n,ans,w;\nunordered_map<int,int> M;\nvector<int> allx[maxx];\nint all[maxx*1000];\nint pd(int i,int j,int k)\n{\n  if(i<0||j<0||k<0||i>=w||j>=w||k>=w) return 0;\nM.clear();\n++M[i];++M[j];++M[k];\nif(M.size()==1)\n{\n  if(allx[i].size()>=3) return allx[i][0]+allx[i][1]+allx[i][2];\n  else return 0;\n}\nelse if(M.size()==2)\n{\n  if(i==j)\n  {if(allx[i].size()>=2&&allx[k].size()>=1) return allx[i][0]+allx[i][1]+allx[k][0];\n  else return 0;}\n  else if(i==k)\n   {if(allx[i].size()>=2&&allx[j].size()>=1) return allx[i][0]+allx[i][1]+allx[j][0];\n  else return 0;}\n  else\n   {if(allx[j].size()>=2&&allx[i].size()>=1) return allx[j][0]+allx[j][1]+allx[i][0];\n    else return 0;}\n}\nelse\n{\n  if(allx[i].size()>0&&allx[j].size()>0&&allx[k].size()>0) return allx[i][0]+allx[j][0]+allx[k][0];\n  return 0;\n}\n}\nint main()\n{\n  cin>>n>>w;\n  for(int i=1;i<=n;++i) cin>>all[i];sort(all+1,all+1+n);\n  for(int i=n;i>=1;--i) allx[all[i]%w].push_back(all[i]);\n\n  for(int i=0;i<w;++i)\n   for(int j=0;j<w;++j)\n   {\n     int k=-(i+j);\n     ans=max(ans,pd(i,j,k));\n     k=w-(i+j);\n     ans=max(ans,pd(i,j,k));\n     k=2*w-(i+j);\n     ans=max(ans,pd(i,j,k));\n   }\n   cout<<ans;\n}\n\n E 正文"},{"aid":"95543","title":"一定要尽可能小的开列表，不然这题很容易爆内存","date":"2023-04-03","likes":0,"views":649,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-倍数问题\n\n解题思路:\n\n注意事项:\n\n参考代码:\nn,k=map(int,input().split())\na=[0]+list(map(int,input().split()))\nst=[[0 for _ in range(3)] for _ in range(k)]\ns=0\nfor i in range(len(a)):\n    if a[i]>st[a[i]%k][0]:\n        st[a[i]%k][2]=st[a[i]%k][1]\n        st[a[i]%k][1]=st[a[i]%k][0]\n        st[a[i]%k][0]=a[i]\n    elif a[i]>st[a[i]%k][1]:\n        st[a[i]%k][2]=st[a[i]%k][1]\n        st[a[i]%k][1]=a[i]\n    elif a[i]>st[a[i]%k][2]:\n        st[a[i]%k][2]=a[i]\nfor i in range(k):#分类讨论\n    for j in range(i,k):\n        t=(k-(i+j)%k)%k#确定两个余数，第三个余数也能确定就少一次循环\n        if i==j:\n            x=st[i][0]\n            y=st[i][1]\n            if t==i:\n                z=st[i][2]\n            else:\n                z=st[t][0]\n        else:\n            x=st[i][0]\n            y=st[j][0]\n            if t==i:\n                z=st[i][1]\n            elif t==j:\n                z=st[j][1]\n            else:\n                z=st[t][0]\n        s=max(s,x+y+z)\nprint(s)\n\n E 正文"},{"aid":"94766","title":"倍数问题(余数问题)","date":"2023-03-12","likes":0,"views":676,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-倍数问题\n\n解题思路:(a+b+c)%k等价于(a%k+b%k+c%k)%k,之所以这样是因为直接暴力a,b,c范围太大超时，采用余数的方法可以减少时间复杂度，对于每个余数\n我们只用找到对应三个最大的数就够用了。\n注意事项:\n\n参考代码:\nfrom sys import maxsize\n\nn, k = map(int, input().split())\nr = [[-maxsize] * 3 for _ in range(k)]\na = [int(i) for i in input().split()]\nfor i in range(n):\n    re = a[i] % k\n    if a[i] > r[re][0]:\n        r[re][0], r[re][1], r[re][2] = a[i], r[re][0], r[re][1]\n    elif a[i] > r[re][1]:\n        r[re][1], r[re][2] = a[i], r[re][1]\n    elif a[i] > r[re][2]:\n        r[re][2] = a[i]\n\nMax = -maxsize\nfor i in range(k):\n    for j in range(k):\n        tmp = (k - i - j) % k  # 第三个余数\n        if i == j:\n            if tmp == i:\n                Max = max(Max, r[i][0] + r[i][1] + r[i][2])\n            else:\n                Max = max(Max, r[i][0] + r[i][1] + r[tmp][0])\n        elif j == tmp:\n            Max = max(Max, r[i][0] + r[j][0] + r[j][1])\n        else:\n            if i == tmp:\n                Max = max(Max, r[i][0] + r[i][1] + r[j][0])\n            else:\n                Max = max(Max, r[i][0] + r[j][0] + r[tmp][0])\n\nprint(Max)\n\n E 正文"},{"aid":"94732","title":"三次循环加剪枝","date":"2023-03-11","likes":0,"views":786,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-倍数问题\n\n解题思路:从最大的数开始枚举，如果遇到小的满足条件的数直接跳出循环\n\n注意事项:\n\n参考代码:\n#include <bits/stdc++.h>\nusing namespace std;\nint n,m,sum,a[100001];\nbool cmp(int x,int y){\n    return x>y;\n}\nint main(){\n    cin>>n>>m;\n    for(int i=1;i<=n;i++)\n        cin>>a[i];\n    sort(a+1,a+n+1,cmp);\n    for(int i=1;i<=n;i++){\n        for(int j=i+1;j<=n;j++){\n            for(int k=j+1;k<=n;k++){\n                if((a[i]+a[j]+a[k])%m==0){\n                    if(a[i]+a[j]+a[k]<=sum)\n                        break;\n                    else sum=a[i]+a[j]+a[k];\n                }\n            }if(a[i]+a[j]+a[3]<=sum)\n                        break;\n        }if(a[i]+a[2]+a[3]<=sum)\n                        break;\n    }\n    cout<<sum;\n    return 0;\n}\n\n E 正文"}],"2278":[{"aid":"103006","title":"动态取平均解决付账问题","date":"2024-03-02","likes":0,"views":893,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-付账问题\n\n Server-side output Markdown text\n\timport java.util.*;\n\tpublic class L付账问题 {\n\tpublic static void main(String[] args) {\n\t\tScanner sc=new Scanner(System.in);\n\t\tint i=0,n=sc.nextInt(),cou=0;\n\t\tdouble s=sc.nextDouble(),co=s/n,bt=0,sum=0,sum1=0,avg=0;\n\t\tdouble a[]=new double[n];\n\t\tfor(i=0;i<n;i++)\n\t\t{\n\t\t\tbt=sc.nextDouble();\n\t\t\tif(bt<co)\n\t\t\t{\n\t\t\t\tcou++;\n\t\t\t\tsum+=(bt-co)*(bt-co);\n\t\t\t\tsum1+=bt;\n\t\t\t}\n\t\t\ta[i]=bt;\n\t\t}\n\t\tArrays.sort(a);\n\t\tdouble t=0;\n\t\tfor(i=cou;i<n;i++)\n\t\t{\n\t\t\tavg=(s-sum1)/(n-cou);\n\t\t\tif(a[i]>=avg) {sum+=(avg-co)*(avg-co)*(n-cou);break;}\n\t\t\telse {sum+=(a[i]-co)*(a[i]-co);}\n\t\t\tsum1+=a[i];\n\t\t\tcou++;\n\t\t}\n\t\tsum=Math.sqrt(sum/n);\n\t\tSystem.out.printf(\"%.4f\",sum);\n\t}\n\t}\n\n E 正文"},{"aid":"95083","title":"【蓝桥杯】付款问题—贪心思想求解","date":"2023-03-20","likes":0,"views":807,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-付账问题\n\n题解分析：\n\n如何求标准差：怎么计算标准差呢\nhttps://jingyan.baidu.com/article/f0062228ecda76bbd2f0c85d.html\n准备就绪，开始：\n1、共需付款 S 元，故每人平均需要付款 S / N ，该值记为 avg；\n2、将 N 个人的所持有的钱数按照从少到多排序\n3、从钱数最少的人开始遍历，将其所持有的金钱 M 与当前的 avg 值进行比较\n        此时若 M < avg：那么该人的钱全部拿来付款；avg 更新（总钱数 - 已付款金额）/ 剩余人数\n        若M > avg ：说明从该人开始以后的每个人都有足够的钱用来付款，不进行凑钱补钱的操作\n总体思想就是：尽可能的让每个人出的钱都与平均值相接近\n//标准差最小\n#include <bits/stdc++.h>\nusing namespace std;\nconst int vinf = 5e5+100;\nlong long int val[vinf];\nint main(){\n\t//输入数据\n\tlong long int n,s;\n\tscanf(\"%lld %lld\",&n,&s);\n\tfor(int i=1;i<=n;++i){\n\t\tscanf(\"%lld\",&val[i]);\n\t}\n\t//数组排序\n\tsort(val+1,val+n+1);\n\tdouble avg = 1.0*s/n;   //平均值\n\tdouble ans = 0.0;\n\t//开始遍历比较\n\tfor(int i=1;i<=n;++i){\n\t\tif(val[i]*(n+1-i) < s) {\n\t\t\tans += (val[i]-avg)*(val[i]-avg);\n\t\t\ts -= val[i];\n\t\t}\n\t\telse {\n\t\t\tdouble pavg = 1.0*s/(n+1-i);\n\t\t\tans += (pavg-avg)*(pavg-avg)*(n+1-i);\n\t\t\tbreak;\n\t\t}\n\t}\n\tprintf(\"%.4lf\",sqrt(ans/n));\n\treturn 0;\n}\n备注：最后实现的方式与我的略有差别，我的也没有通过测试，暂时就以这个为准！\n\n E 正文"},{"aid":"78910","title":"萌新的比较工整的代码","date":"2021-05-05","likes":0,"views":887,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-付账问题\n\n解题思路:\n\n注意事项:\n（1）注意double精度不够，用long double\n（2）避开所有人钱都一样的坑，直接输出0\n\n参考代码:\n#include <iostream>\n#include <vector>\n#include <iomanip>\n#include <cmath>\nusing namespace std;\ntypedef long double ld;\nmain()\n{\n\t        int n;cin>>n;\n\t        ld s;cin>>s;\n\n\t        vector<ld> a;\n\t        ld x;\n\t        for(int i=0;i<n;i++) cin>>x,a.push_back(x);\n\n\t        bool flag=true;\n\t        for(int i=1;i<n;i++)\n\t\t                if(a[i]!=a[0]) {flag=false;break;}\n\t        if(flag)\n\t        {\n\t\t            cout<<fixed<<setprecision(4)<<0.0;\n\t\t            exit(0);\n\t        }\n\n\t        vector<ld> pay;\n\t        while(true)\n\t        {\n\t\t                int len=a.size();\n                ld avg=s/len;\n\n\t\t                vector<ld> na;\n\t\t                int count=0;\n\t\t                for(int i=0;i<len;i++)\n\t\t\t                if(a[i]>avg) na.push_back(a[i]);\n\t\t\t                else s-=a[i],count++,pay.push_back(a[i]);\n\n\t\t                a.clear();a=na;\n\t\t                if(count==0) break;\n\t        }\n\n\t        int len=a.size();\n\t        ld avg=s/len;\n\t        for(int i=0;i<len;i++) pay.push_back(avg);\n\n\t        ld sum=0,sumd=0;\n\t        for(int i=0;i<n;i++)\n\t\t        sum+=pay[i],sumd+=pay[i]*pay[i];\n\n\t        sum/=n;sumd/=n;\n\t        ld r=abs(sumd-sum*sum);\n\t        cout<<fixed<<setprecision(4)<<sqrt(r);\n}\n\n E 正文"},{"aid":"72450","title":"蓝桥杯2018年第九届真题-付账问题-题解（C++代码）","date":"2020-09-01","likes":0,"views":1736,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-付账问题\n\n Server-side output Markdown text\n```cpp\n/*付账问题\n\n【题目描述】\n几个人一起出去吃饭是常有的事。但在结帐的时候，常常会出现一些争执。\n\n现在有 n 个人出去吃饭，他们总共消费了 S 元。其中第 i 个人带了 ai 元。幸运的是，所有人带的钱的总数是足够付账的，但现在问题来了：每个人分别要出多少钱呢？\n\n为了公平起见，我们希望在总付钱量恰好为 S 的前提下，最后每个人付的钱的标准差最小。这里我们约定，每个人支付的钱数可以是任意非负实数，即可以不是1分钱的整数倍。你需要输出最小的标准差是多少。\n\n标准差的介绍：标准差是多个数与它们平均数差值的平方平均数，一般用于刻画这些数之间的“偏差有多大”。形式化地说，设第 i 个人付的钱为 bi 元，那么标准差为 : [参见 2018 10 付账问题.png]\n\n【输入格式】\n从标准输入读入数据。\n\n第一行包含两个整数 n、S；\n第二行包含 n 个非负整数 a1, ..., an。\n\n【输出格式】\n输出到标准输出。\n\n输出最小的标准差，四舍五入保留 4 位小数。\n保证正确答案在加上或减去 10^-9 后不会导致四舍五入的结果发生变化。\n\n【样例1输入】\n5 2333\n666 666 666 666 666\n\n【样例输出】\n0.0000\n\n【样例解释】\n每个人都出 2333/5 元，标准差为 0。\n\n再比如：\n【样例输入】\n10 30\n2 1 4 7 4 8 3 6 4 7\n\n【样例输出】\n0.7928\n\n【数据说明】\n对于 10% 的数据，所有 ai 相等；\n对于 30% 的数据，所有非 0 的 ai 相等；\n对于 60% 的数据，n≤1000；\n对于 80% 的数据，n≤10^5；\n对于所有数据，n≤5×10^5, 0≤ai≤10^9。\n\n资源约定：\n峰值内存消耗（含虚拟机） < 256M\nCPU消耗 < 1000ms\n\n请严格按要求输出，不要画蛇添足地打印类似：“请您输入...” 的多余内容。\n\n注意：\nmain函数需要返回0;\n只使用ANSI C/ANSI C++ 标准;\n不要调用依赖于编译环境或操作系统的特殊函数。\n所有依赖的函数必须明确地在源文件中 #include <xxx>\n不能通过工程设置而省略常用头文件。\n\n提交程序时，注意选择所期望的语言类型和编译器类型。\n*/\n\n#include<bits/stdc++.h>\n\nusing namespace std;\n\nint main() {\n\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n    cout.tie(NULL);\n\n    long long n, S;//人数与总额\n\n    double ans = 0, avg;\n\n    cin >> n >> S;\n\n    avg = 1.0 * S / n;//总平均值是固定不变的\n\n    long long *a = new long long[n];\n\n    for (int i = 0; i < n; ++i) {\n        cin >> a[i];\n    }\n\n    sort(a, a + n);\n\n    for (int i = 0; i < n; ++i) {\n        if (a[i] * (n - i) < S) {//钱的数额*分摊的人数<总额=>当前的数额小于当前均值的=>全部贡献出来\n            ans += (a[i] - avg) * (a[i] - avg);//累加到方差\n            S -= a[i];//应支付的总额变小\n        } else {//当前及后续每个人的数额都超出当前均值\n            double cur_avg = 1.0 * S / (n - i);//算出一个当前均值，就是每个人应该付的数额\n            ans += (avg - cur_avg) * (avg - cur_avg) * (n - i);\n            break;\n        }\n    }\n\n    cout << fixed << setprecision(4) << sqrt(ans / n) << '\\n';\n\n    return 0;\n}\n```\n\n E 正文"},{"aid":"69672","title":"蓝桥杯2018年第九届真题-付账问题-题解(C++代码)","date":"2020-04-21","likes":0,"views":1715,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-付账问题\n\n Server-side output Markdown text\n\n### 排序 + 贪心\n\n有一个总的平均值 avg ，如果每个人支付的钱越靠近 avg ，方差就越小。\n\n还有一个动态的当前均值 aver。\n\n将每个人身上带的钱从小到大排序后，带的钱小于当前均值则付出全部的钱。如果第 i 个人带的钱大于等于当前均值，则他及他之后的的人都能够支付当前均值。\n\n```c++\n#include<bits/stdc++.h>\nusing namespace std;\n\nint main(){\n\tint n;\n\tdouble s;\n\tcin>>n>>s;\n\tdouble a[n];\n\tint i;\n\tfor(i=0;i<n;i++){\n\t\tcin>>a[i];// 每个人身上带了多少钱\n\t}\n\tsort(a,a+n); // 排序\n\tdouble avg = s/n; //  固定不变的总平均值\n\tdouble aver = avg; // 会变动的当前均值\n\tdouble ans = 0;\n\tfor(i = 0; i < n; i++){\n\t\taver = s / (n - i);//\n\t\tif(a[i] - aver < 0){\n\t\t\t ans += (a[i] - avg) * (a[i] - avg);\n\t\t\ts = s - a[i]; // 需要付的总钱数发生了变化，aver 也随之变化\n\t\t}\n\t\telse{// 如果当前这个人拥有的钱数足以支付平均值，那么说明后面的人也都能\n\t\t\t\t// 则，无论他有多少钱，只需要支付自己的那一部分，即当前的平均数\n\t\t\tans += (avg - aver) * (avg - aver) * (n - i);\n\t\t\tbreak;\n\t\t}\n\t}\n\tprintf(\"%.4lf\",sqrt(ans/n));//开根号  四舍五入保留四位小数\n\treturn 0;\n}\n\n```\n\n E 正文"}],"2279":[{"aid":"104210","title":"蓝桥杯2018年第九届真题-日志统计","date":"2024-04-06","likes":0,"views":470,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-日志统计\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\nstruct node\n{\n\tint t,id;\n}x[100005],t;\nbool cmp(node a,node b)\n{\n\tif(a.t==b.t)\n\t{\n\t\treturn a.id<b.id;\n\t}\n\treturn a.t<b.t;\n}\nqueue<node>q;\nint f[100005];\nset<int>se;\nint main()\n{\n\tint n,d,k;\n\tscanf(\"%d%d%d\",&n,&d,&k);\n\tfor(int i=0;i<n;i++)\n\t{\n\t\tscanf(\"%d%d\",&x[i].t,&x[i].id);\n\t}\n\tsort(x,x+n,cmp);\n\tfor(int i=0;i<n;i++)\n\t{\n\t\tt=q.front();\n\t\twhile(!q.empty()&&x[i].t-t.t>=d)\n\t    {\n\t\t    f[t.id]--;\n\t    \tq.pop();\n\t    \tt=q.front();\n\t    }\n\t\tif(x[i].t-t.t<d||q.empty())\n\t\t{\n\t\t\t//cout<<x[i].id<<' '<<i<<endl;\n\t\t\tf[x[i].id]++;\n\t\t\tq.push(x[i]);\n\t\t}\n\t\tif(f[x[i].id]==k)\n\t\t{\n\t\t\tse.insert(x[i].id);\n\t\t}\n\t}\n\tfor(auto i=se.begin();i!=se.end();i++)\n\t{\n\t\tprintf(\"%d\\n\",*i);\n\t}\n\treturn 0;\n}\n\n E 正文"},{"aid":"102539","title":"双指针，从输入的角度出发，sort刷一遍，在d时间段内找到获赞数符合条件的id，双指针来处理其中重复的操作，使得每次只会++，比多重循环减少了大量时间，由哦（n2）减少到接近o（n）","date":"2024-02-06","likes":0,"views":593,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-日志统计\n\n Server-side output Markdown text\n\n```\n#include <bits/stdc++.h>\n#define int long long\n#define x first\n#define y second\nusing namespace std;\nconst int N=100010;\nint n,d,k;\npair<int,int> ti[N];\nint sb[N],re[N];\nsigned main()\n{\n\tcin>>n>>d>>k;\n\tfor(int i=0;i<n;i++)\n\t{\n\t\tcin>>ti[i].x>>ti[i].y;\n\t}\n\tsort(ti,ti+n);\n\tfor(int i=0,j=0;i<n;i++)\n\t{\n\t\tsb[ti[i].y]++;\n\t\twhile(ti[i].x-ti[j].x>=d)\n\t\t{\n\t\t\tsb[ti[j].y]--;\n\t\t\tj++;\n\t\t}\n\t\tif(sb[ti[i].y]>=k)\n\t\t{\n\t\t\tre[ti[i].y]=1;\n\t\t}\n\t}\n\tfor(int i=0;i<=100000;i++)\n\t{\n\t\tif(re[i]==1)\n\t\t{\n\t\t\tcout<<i<<'\\n';\n\t\t}\n\t}\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"98103","title":"蓝桥杯2018年第九届真题-日志统计(复杂度O(nlogn))","date":"2023-08-20","likes":0,"views":674,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-日志统计\n\n解题思路:\n首先记录每个日志的点赞时间，对每个日志的时间排序后，直接判断当前点赞时间和后k个时间是否差值小于d。\n注意事项:\n复杂度O(nlogn)\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n#define maxx 110000\nint k,a,b,n,m,d;\nvector<int> all[maxx];\nvector<int> ans;\nint main()\n{\n  cin>>n>>d>>k;\n  for(int i=1;i<=n;++i)\n  {cin>>b>>a;\n   m=max(a,m);\n   all[a].push_back(b);\n  }\n  for(int i=0;i<=m;++i)  sort(all[i].begin(),all[i].end());\n  for(int i=0;i<=m;++i)\n  for(int j=0;j+k-1<all[i].size();++j)\n   if(all[i][j+k-1]-all[i][j]<d)\n    {ans.push_back(i);\n    break;}\n  for(int i=0;i<ans.size();++i) cout<<ans[i]<<\"\\n\";\n}\n\n E 正文"},{"aid":"95206","title":"蓝桥杯2018年第九届真题-日志统计-JAVA双指针-分情况讨论","date":"2023-03-24","likes":0,"views":662,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-日志统计\n\n Server-side output Markdown text\n用一**个Map来存储输入的数据，以热帖id为键，被点赞的时刻用一个List保存起来做值**，便于后续判断该帖子是否为热帖\n存储完输入数据后，分别**对每个键对应的List从大到小排序，再遍历**，判断该键对应的id是否为热帖\n用一个指针i从下标0开始遍历【一直遍历到len-1】，指针j从最后一个开始遍历【直到j<=i为止，**这里一定要包括j==i的情况，否则会得到的结果可能会小1**】，然后对list[j]~list[i]区间进行分情况讨论判断即可得到答案\n\n\timport java.util.ArrayList;\n    import java.util.HashMap;\n    import java.util.List;\n    import java.util.Map;\n    import java.util.Scanner;\n\n    public class Main {\n\n    \tpublic static void main(String[] args) {\n    \t\t// TODO Auto-generated method stub\n    \t\tScanner sc = new Scanner(System.in);\n    \t\tint n =sc.nextInt();\n    \t\tint d = sc.nextInt();\n    \t\tint k = sc.nextInt();\n    \t\t// 输入数据保存到map中\n    \t\tHashMap<Integer, List<Integer>> map = new HashMap<>();\n    \t\tint key,val;\n    \t\tfor(int i=0;i<n;i++) {\n    \t\t\tval = sc.nextInt();\n    \t\t\tkey = sc.nextInt();\n    \t\t\tList<Integer> list;\n    \t\t\tif(map.containsKey(key)) {\n    \t\t\t\tlist = map.get(key);\n    \t\t\t}else {\n    \t\t\t\tlist = new ArrayList<>();\n    \t\t\t}\n    \t\t\tlist.add(val);\n    \t\t\tmap.put(key, list);\n    \t\t}\n\n    \t\tList<Integer> temp; // 定义每个键对应的list\n    \t\tList<Integer> res = new ArrayList<>(); // 存储结果\n    \t\tint v; //存储每个帖子在区间内的最大点赞数\n    \t\tfor(Map.Entry<Integer, List<Integer>>entry:map.entrySet()) {\n    \t\t\tv = 0; // 遍历每个list前都初始化为0\n    \t\t\ttemp = entry.getValue();\n    \t\t\ttemp.sort((o1,o2)->(o1-o2)); //对点赞时间进行排序\n    \t\t\tfor(int i=0;i<temp.size();i++) { //i从小到大遍历\n    \t\t\t\tfor(int j=temp.size()-1;j>=i;j--) { //j从大到小遍历\n\t\t\t\t\t\t//如果当前temp[j]-temp[i]大于d，说明当前temp[j]太大\n    \t\t\t\t\tif((temp.get(j)-temp.get(i))>d) continue;\n\t\t\t\t\t\t// 如果当前temp[j]-temp[i]小于d，此时[i,j]的点赞都是符合要求的，计算[i,j]的长度和v进行比较\n    \t\t\t\t\telse if((temp.get(j)-temp.get(i))<d){\n    \t\t\t\t\t\tif((j-i+1)>v) {\n    \t\t\t\t\t\t\tv = j-i+1;\n    \t\t\t\t\t\t\tbreak;\n    \t\t\t\t\t\t}\n    \t\t\t\t\t}\n\t\t\t\t\t\t// 如果当前temp[j]-temp[i]等于d，此时[i,j)的点赞都是符合要求的，计算[i,j)的长度和v进行比较\n\t\t\t\t\t\telse { //相等\n    \t\t\t\t\t\tif((j-i)>v) {\n    \t\t\t\t\t\t\tv = j-i;\n    \t\t\t\t\t\t\tbreak;\n    \t\t\t\t\t\t}\n    \t\t\t\t\t}\n    \t\t\t\t}\n    \t\t\t}\n\t\t\t\t// 看v是否不小于k【即当前帖子是否为热帖】，是的话则将id存储到结果集中\n    \t\t\tif(v>=k) res.add(entry.getKey());\n    \t\t}\n\n\t\t\t// 从小到大输出结果\n    \t\tres.sort((o1,o2)->(o1-o2));\n    \t\tfor(Integer i:res) {\n    \t\t\tSystem.out.println(i);\n    \t\t}\n    \t}\n\n    }\n\n E 正文"},{"aid":"94950","title":"2279: 蓝桥杯2018年第九届真题-日志统计（Java写法） 里面代码每行都有详细的解释，相信可以帮助你看懂","date":"2023-03-17","likes":0,"views":805,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-日志统计\n\n解题思路:\n\n注意事项:\n这里我写的尺取法可能有点不一样，但是整体思想是差不多的，这里写的就是每次当前ID在这个时间段有没有出现K次，多了也不用管，直接输出，题目说得从小到大，我试了一下好像不用，不过影响也不大，判断完了直接换下一个不一样，所以需要一个flag来标记，再一个可能i-1不能理解，你可以把他想象成为一个从头开始的for吧。详细的看下面代码理解\n\n参考代码:\npackage 搜索;\n\nimport java.util.Arrays;\nimport java.util.Scanner;\n\npublic class T2279日志统计 {\n\tpublic static void main(String args[]) {\n\t\tint n, d, k; // 输入的N行每行一条日志，包含两个整数ts 和id。\n\t\tScanner sc = new Scanner(System.in);\n\t\tn = sc.nextInt();\n\t\td = sc.nextInt();\n\t\tk = sc.nextInt();\n\t\tClickHot arr[] = new ClickHot[n];\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\tint time = sc.nextInt();\n\t\t\tint id = sc.nextInt();\n\t\t\tarr[i] = new ClickHot(time, id); // 存放每组数字\n\t\t}\n\t\tArrays.sort(arr); // 对其进行排序\n\t\tint parentId = arr[0].id; // 先拿到第一个id\n\t\tboolean flag =false; // 设置一个标志\n\t\tfor (int i = 0; i < n; i++) {\n\t\t\t// 我当前得id如果有k个赞得话，就是热帖\n\t\t\t// 当前位置和以后的k个位置上都是此id，就有k个赞\n\t\t\t// 并且时间差小于d，并且没有被输出过\n\t\t\tif (i + k - 1 < n && arr[i + k - 1].id == parentId && arr[i + k - 1].ts - arr[i].ts < d && !flag  )\n\n\t\t\t{\n\t\t\t\tSystem.out.println(parentId); // 输出这个id 因为题目中只要求输出在同一个时间段有两个赞即可\n\t\t\t\tflag = true;// 这步设置变量，当后面来相同的，但是我不需要输出了，因为两个已经够了\n\t\t\t} else if (arr[i].id != parentId) // 这步是如果我不相同id值，那么我就把这个当前的id用我现在i数组中对应的id取代\n\t\t\t{\n\t\t\t\tparentId = arr[i].id; // 把先前的id替换\n\t\t\t\tflag = false; // 重新设置标志\n\t\t\t\ti = i - 1; // 因为我把上面一个设置了，此时我需要向上减一，然后再做比较，\n\t\t\t\t//这样相当于我开始时候i不做变换没我把该取代的值取代掉\n\t\t\t}\n\t\t}\n\t}\n}\n\nclass ClickHot implements Comparable<ClickHot> // 创建一个ClickHot类留存放两个每次的两个数字 一个是\n\t\t\t\t\t\t\t\t\t\t\t\t// ts 是td\n{\n\tint ts, id;\n\n\tClickHot(int ts, int id) // 两个变量\n\t{\n\t\tthis.ts = ts;\n\t\tthis.id = id;\n\t}\n\n\t@Override\n\tpublic int compareTo(ClickHot o) {\n\t\tif (id == o.id) // 先对id做比较其次id相同对ts做比较\n\t\t\treturn ts - o.ts;\n\t\telse\n\t\t\treturn id - o.id;\n\t}\n\n}\n\n E 正文"}],"2280":[{"aid":"86347","title":"蓝桥杯2018年第九届真题-乘积最大","date":"2022-04-06","likes":0,"views":989,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-乘积最大\n\n Server-side output Markdown text\n```cpp\n#include<iostream>\n#include<algorithm>\nusing namespace std;\ntypedef long long LL;\nconst int N = 100000;\nconst int mod = 1000000009;\nint n,k;\nint a[N+1];\nint main(){\n\tcin>>n>>k;\n\tfor(int i=0;i<n;i++)\n\t\tcin>>a[i];\n\tsort(a,a+n);\n\tLL res=1;\n\tint l=0,r=n-1;\n\tint sign = 1;\n\tif(k&1){//k为奇数\n\t\tres=a[r--];//取最大的数\n\t\tk--;//k变为偶数\n\t\tif(res<0)//说明全部为负数\n\t\t\tsign=-1;//根据最大值的正负，改变符号\n\t}\n\twhile(k){//此时k必为偶数，偶数就好处理了，两个两个取就可以了,并且一定是取最左边或者最右边的两个\n\t\tLL x=(LL)a[l]*a[l+1];//取最小的两个数的乘积\n\t\tLL y=(LL)a[r]*a[r-1];//取最大的两个数的乘积\n\t\tif(x*sign>y*sign){\n\t\t\tres=x%mod*res%mod;\n\t\t\tl+=2;\n\t\t}\n\t\telse{\n\t\t\tres=y%mod*res%mod;\n\t\t\tr-=2;\n\t\t}\n\t\tk-=2;\n\t}\n\tcout<<res<<endl;\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"73267","title":"蓝桥杯2018年第九届真题-乘积最大-题解（C++代码）","date":"2020-10-13","likes":0,"views":1341,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-乘积最大\n\n Server-side output Markdown text\n### 解题思路：\n### 1、如果k==n的话，那么全部数字都要选\n### 2、如果k%2==0(即k为偶数)，那么选出来的一个是非负数\n### 3、如果k%2==1(即k为奇数)分两种：\n### （1）如果全部都为负数，那么全部都为负数，把最大最大负数取出来，然后变成了k为偶数的情况，要把符号改变过来\n### （2）否则的话,则一定至少有 1个非负数, 那么我们将最大的数取出来,然后变成了k为偶数的情况。\n```cpp\n#include<bits/stdc++.h>\n#define x first\n#define y second\n#define mem1(h) memset(h,-1,sizeof h)\n#define mem0(h) memset(h,0,sizeof h)\n#define mcp(a,b) memcpy(a,b,sizeof b)\nusing namespace std;\ntypedef long long LL;\ntypedef unsigned long long ull;\ntypedef pair<int,int>PII;\ntypedef pair<double,double>PDD;\nnamespace IO{\n\tinline LL read(){\n\t\tLL o=0,f=1;char c=getchar();\n\t\twhile(c<'0'||c>'9'){if(c=='-')f=-1;c=getchar();}\n\t\twhile(c>='0'&&c<='9'){o=o*10+c-'0';c=getchar();}\n\t\treturn o*f;\n\t}\n}using namespace IO;\n//#############以上是自定义技巧（可忽略）##########\nconst int N=1e5+7,M=2e5+7,INF=0x3f3f3f3f,mod=1e9+9,P=131;\nint n,k;\nint a[N];\nint main(){\n    cin>>n>>k;\n    for(int i=0;i<n;i++){\n    \tcin>>a[i];\n\t}\n\tsort(a,a+n);\n\tint res=1;\n\tint l=0,r=n-1;\n\tint sign=1;\n\tif(k&1){//k为奇数\n\t\tres=a[r--];//取最大的数\n\t\tk--;\n\t\tif(res<0)sign=-1;//如果是最大为负数，要改变符号\n\t}\n\twhile(k){//k为偶数的情况\n\t\tLL x=(LL)a[l]*a[l+1],y=(LL)a[r]*a[r-1];//取最小的两个与最大两个数乘积\n\t\tif(x*sign>y*sign){//看两个数与当前符号相乘哪个大取哪个\n\t\t\tres=x%mod*res%mod;\n\t\t\tl+=2;\n\t\t}else{\n\t\t\tres=y%mod*res%mod;\n\t\t\tr-=2;\n\t\t}\n\t\tk-=2;\n\t}\n\tcout<<res<<endl;\n    return 0;\n}\n```\n\n E 正文"},{"aid":"72342","title":"蓝桥杯2018年第九届真题-乘积最大-题解（C++代码）","date":"2020-08-26","likes":0,"views":1881,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-乘积最大\n\n Server-side output Markdown text\n```cpp\n/*乘积最大\n\n给定N个整数A1, A2, ... AN。请你从中选出K个数，使其乘积最大。\n\n请你求出最大的乘积，由于乘积可能超出整型范围，你只需输出乘积除以1000000009的余数。\n\n注意，如果X<0， 我们定义X除以1000000009的余数是负(-X)除以1000000009的余数。\n即：0-((0-x) % 1000000009)\n\n【输入格式】\n第一行包含两个整数N和K。\n以下N行每行一个整数Ai。\n\n对于40%的数据，1 <= K <= N <= 100\n对于60%的数据，1 <= K <= 1000\n对于100%的数据，1 <= K <= N <= 100000  -100000 <= Ai <= 100000\n\n【输出格式】\n一个整数，表示答案。\n\n【输入样例】\n5 3\n-100000\n-10000\n2\n100000\n10000\n\n【输出样例】\n999100009\n\n再例如：\n【输入样例】\n5 3\n-100000\n-100000\n-2\n-100000\n-100000\n\n【输出样例】\n-999999829\n\n资源约定：\n峰值内存消耗（含虚拟机） < 256M\nCPU消耗  < 1000ms\n\n请严格按要求输出，不要画蛇添足地打印类似：“请您输入...” 的多余内容。\n\n注意：\nmain函数需要返回0;\n只使用ANSI C/ANSI C++ 标准;\n不要调用依赖于编译环境或操作系统的特殊函数。\n所有依赖的函数必须明确地在源文件中 #include <xxx>\n不能通过工程设置而省略常用头文件。\n\n提交程序时，注意选择所期望的语言类型和编译器类型。\n*/\n\n#include <bits/stdc++.h>\n\nusing namespace std;\n\nconst long long MOD = 1000000009;\n\nconst int maxN = 100005;\n\nint n, k;\n\nvector<long long> pos, neg;//保存正数和负数的列表\n\nlong long ans;\n\n/**\n * 将数组a中[start,end]区间内的数连乘起来\n * @param a\n * @param start\n * @param end\n * @param flag\n * @return\n */\nlong long mul(vector<long long> a, int start, int end) {\n    long long ans = 1;\n\n    for (int i = start; i <= end; ++i) {\n        ans = ans * a[i] % MOD;\n    }\n    return ans;\n}\n\nint main() {\n    cin >> n >> k;\n    for (int i = 1; i <= n; i++) {\n        long long x;\n        cin >> x;\n        if (x > 0)pos.push_back(x);\n        if (x < 0)neg.push_back(x);//只处理正数和负数，0不处理\n    }\n    sort(pos.begin(), pos.end());\n    sort(neg.begin(), neg.end());\n/*===========下面开始分类讨论=========*/\n    unsigned long sizeSum = pos.size() + neg.size();\n//    1.正数和负数的个数不足k，必然有0的存在\n    if (sizeSum < k) {\n        ans = 0;\n    }\n//    2.正数和负数的个数恰好为k\n    else if (sizeSum == k) {\n//      2.1 k与n相等，必须选这k个数，没有0\n        if (k == n) {\n            ans = mul(pos, 0, pos.size() - 1) * mul(neg, 0, neg.size() - 1) % MOD;\n        }\n//      2.2 k<n，有0的存在\n        else {\n//          2.2.1 可得正数解当且仅当:正数全部选中，负数全部选中且为偶数个\n            if (neg.size() % 2 == 0) {\n                ans = mul(pos, 0, pos.size() - 1) * mul(neg, 0, neg.size() - 1) % MOD;\n            } else {\n//          2.2.2 负数是奇数个，全部选中结果为负数，不全部选中可得0，结果就是0\n                ans = 0;\n            }\n        }\n    } else {\n//    3.正数和负数的个数大于k，情况比较复杂\n//    sum>k\n//      3.1 没有正数,负数和0中选k个\n        if (pos.size() == 0) {\n            if (k % 2 == 0) {//k是偶数\n                ans = mul(neg, 0, k - 1);//正向选k个\n            } else {\n                if (sizeSum < n)//有0\n                    ans = 0;\n                else//没有0，必须从所有负数中选奇数个数=》连乘绝对值小的\n                    ans = mul(neg, neg.size() - k, neg.size() - 1);//逆向选k个\n            }\n//      3.2 没有负数\n        } else if (neg.size() == 0) {\n            ans = mul(pos, pos.size() - k, pos.size() - 1);//逆向选k个\n//      3.3 有正数也有负数\n        } else {\n            int posStart;\n            int negEnd;\n            if (k >= pos.size()) {//正数不足k个\n                //          假定正数全部选中，剩余偶数个负数，等会再来挪动标尺\n                if ((k - pos.size()) % 2 == 0) {\n                    negEnd = k - pos.size() - 1;//负数选择的截止下标\n                    posStart = 0;//正数选择的起始下标\n                } else {\n                    //          剩余个数是奇数，正数先少选一个\n                    posStart = 1;//正数选择的起始下标\n                    negEnd = k - pos.size();//负数选择的截止下标\n                }\n            } else {//正数多余k个，假定从正数中先选最大的k个\n//                if(k%2==0){ //k是偶数\n                negEnd = -1;\n                posStart = pos.size() - k;\n//                }else{//k是奇数，先少选一个\n//                    negEnd=-1;\n//                    posStart = pos.size()-1-k;\n//                }\n            }\n//          双标尺移动\n            while (negEnd + 2 < neg.size() && posStart + 2 < pos.size() &&\n                   neg[negEnd + 1] * neg[negEnd + 2] > pos[posStart] * pos[posStart + 1]) {\n                negEnd += 2;\n                posStart += 2;\n            }\n            ans = mul(neg, 0, negEnd) * mul(pos, posStart, pos.size() - 1) % MOD;\n        }\n    }\n\n    cout << ans << endl;\n\n    return 0;\n}\n```\n\n E 正文"},{"aid":"71228","title":"蓝桥杯2018年第九届真题-乘积最大-题解（C++代码）","date":"2020-07-15","likes":0,"views":2311,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-乘积最大\n\n Server-side output Markdown text\n# MarkDown编辑器基本使用说明\n\n**思路：\nN个数选K个数 K<=N\nN个数中负数size1个，正数size2个，一共size个（不包含0）\n将正数分到正数组，负数分到负数组，并将两个数组从小到大排序\n1.size<K\n\t必须选择0 ans=0\n\n2.size=K\n\t2.1 size1是偶数   ans=非0数累乘\n\n\t2.2 size1不是偶数\n\t\t2.2.1 K<N 说明有0存在，ans=0\n\t\t2.2.2 K=N 说明无0存在，ans=全部累乘\n\n3.size>K\n\t3.1 没有正数\n\t\t3.1.1 K为偶数，ans=绝对值最大的那K个负数累乘\n\t\t3.1.2 K为奇数\n\t\t\t3.1.2.1 size<N ans=0\n\t\t\t3.1.2.2 size=N ans=绝对值最小的那K个负数累乘\n\t3.2 没有负数 ans=最大的那K个正数累乘\n\t3.3 有正有负（寻找正数组、负数组的起始游标）\n\t\t3.3.1 正数不足k个，假定正数全部选中，剩余偶数个负数，等会再来挪动标尺\n\t\t\t选完正数后，剩余可选个数是奇数，正数先少选一个\n\t\t3.3.2 正数多于k个，假定从正数中先选最大的k个\n\t\t\t3.3.2.1 k是偶数 起始游标：正数组 size1-1   负数组 0\n\t\t\t3.3.2.2 k是奇数\t起始游标：正数组 size1-2 负数组 0\n\t\t双标尺移动\n\t\t作用：寻找累乘正数组与负数组哪一段。\n\t\t操作：看负数游标起始位置随后的两个负数相乘是否大于正数，游标位置随后的两个正数相乘。\n    #include<bits/stdc++.h>\n    #define ll long long\n    const ll mod = 1e9+9;\n    ll ans=1, N, K, sz[100010], k=0;\n    int flag=0;\n    using namespace std;\n    bool cmp(ll a,ll b){\n    \treturn a>b;\n    }\n    int main()\n    {\n    \tcin>>N>>K;\n    \tfor(int i=0; i<N; i++){\n    \t\tcin>>sz[i];\n    \t\tif(sz[i]>0) flag=1;\n    \t}\n    \tif(flag==0){\n    \t\tif(K%2==1){\n    \t\tsort(sz,sz+N,cmp);\n    \t\tlong long sum=1;\n    \t\tfor(int i=0;i<K;i++)\n    \t\t{\n    \t\t\t//cout<<sz[i];\n    \t\t\tsum*=sz[i];\n    \t\t\tsum%=mod;\n    \t\t}\n    \t\tcout<<sum;\n    \t\treturn 0;\n    \t\t}\n    \t\telse{\n    \t\tsort(sz,sz+N);\n    \t\tlong long sum=1;\n    \t\tfor(int i=0;i<K;i++)\n    \t\t{\n    \t\t\t//cout<<sz[i];\n    \t\t\tsum*=sz[i];\n    \t\t\tsum%=mod;\n    \t\t}\n    \t\tsum%=mod;\n    \t\tcout<<sum;\n    \t\treturn 0;\n    \t\t}\n\n    \t}\n\n    \tsort(sz, sz+N);\n    \tll l=0, r=N-1;\n\n    \twhile(k!=K)\n    \t{\n    \t\tif(sz[l]*sz[l+1] > sz[r]*sz[r-1] && K-k >= 2)\n    \t\t{\n    \t\t\tans = ((ans * sz[l])%mod * sz[l+1])%mod;\n    \t\t\tl = l + 2;\n    \t\t\tk += 2;\n    \t\t}\n    \t\telse\n    \t\t{\n    \t\t\tans = (ans * sz[r])%mod;\n    \t\t\tr = r - 1;\n    \t\t\tk++;\n    \t\t}\n    \t}\n    \tcout<<ans;\n\n    \treturn 0;\n    }\n\n E 正文"}],"2281":[{"aid":"108774","title":"刚学STL的小白","date":"2025-03-12","likes":0,"views":662,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-次数差\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n\nmap<char,int> mp;\nint a,b = 1000;\n\nint main()\n{\n\t    string s;\n\t    cin>>s;\n\t    for(int i = 0;i < s.size();++i)\n\t    {\n\t\t        mp[s[i]]++;\n\t    }\n\t    for(int i = 0;i < s.size();++i)\n\t    {\n\t\t        a = max(a,mp[s[i]]);\n\t\t        b = min(b,mp[s[i]]);\n\t    }\n\t    cout<<a - b<<endl;\n\t    return 0;\n}\n\n E 正文"},{"aid":"103370","title":"java--study||O.o","date":"2024-03-13","likes":0,"views":632,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-次数差\n\n参考代码:\nimport java.util.Scanner;\n\npublic class Main\n{   public static void main(String[] args)\n    {   Scanner scanner = new Scanner(System.in);\n        String s = scanner.next();\n        int[] hash = new int[26];\n        for(int i = 0; i < s.length(); i++)\n        {   char c = s.charAt(i);\n            int index = c - 'a';\n            hash[index]++;\n        }\n        int max = 0;\n        int min = 0;\n        for(int i = 0; i < 26; i++)\n        {   if(max == 0 && min == 0 && hash[i] > 0)\n            {   max = hash[i];\n                min = hash[i];\n            }\n            if(hash[i] > 0)\n            {   max = Math.max(max, hash[i]);\n                min = Math.min(min, hash[i]);\n            }\n        }\n            System.out.print(max - min);\n    }\n}\n\n E 正文"},{"aid":"102383","title":"蓝桥杯2018年第九届真题-次数差  简单易懂","date":"2024-02-01","likes":0,"views":607,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-次数差\n\n解题思路:利用数组存储每个字母出现的次数，用函数比较出最大最小值相减\n\n注意事项:数组应全部初始值为0\n\n参考代码:\n#include <iostream>\n#include <cstring>\n#include <vector>\n#include <algorithm>\n#include <cmath>\n#include <iomanip>\n#include <string>\nusing namespace std;\nint main()\n{\n    string s;\n    cin>>s;\n    int i,n;\n    int a[26]={0};\n    n=s.size();//字符串长度\n    for(i=0;i<n;i++)\n    {\n       a[s[i]-'a']++;//每个字母出现个数\n    }\n    int maxn=0,minn=200000;//定义最大最小\n    for(i=0;i<26;i++)\n    {   if(a[i]!=0)//前提一定是不等于0\n        {maxn=max(maxn,a[i]);\n        minn=min(minn,a[i]);\n        }\n    }\n    cout<<maxn-minn;\n}\n\n E 正文"},{"aid":"98109","title":"蓝桥杯2018年第九届真题-次数差","date":"2023-08-20","likes":0,"views":720,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-次数差\n\n解题思路:\n利用字母ascii码进行统计。\n注意事项:\n出现0次不计入最小值\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\nint mxx,mnn;\nstring s;\nint all[30];\nint main()\n{\n  cin>>s;\n  for(int i=0;i<s.size();++i)  ++all[s[i]-'a'];\n  mxx=0;mnn=s.size();\n  for(int i='a';i<='z';++i)\n  { if(all[i-'a']==0) continue;\n    mxx=max(all[i-'a'],mxx);\n  mnn=min(all[i-'a'],mnn);}\n  cout<<mxx-mnn;\n}\n\n E 正文"},{"aid":"95633","title":"蓝桥杯2018年第九届真题-次数差","date":"2023-04-05","likes":0,"views":555,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-次数差\n\n解题思路:\n\n注意事项:\n\n参考代码:\nL = input()\nn = L.count(max(L,key=L.count))\nm = L.count(min(L,key=L.count))\nprint(n-m)\n\n E 正文"}],"2282":[{"aid":"86694","title":"蓝桥杯2018年第九届真题-等腰三角形","date":"2022-04-19","likes":0,"views":835,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-等腰三角形\n\n解题思路:\n\n注意事项:\n\n参考代码:\nn=int(input())\ns=''\nfor i in range(1,1000):\n    s+=str(i)\nl=[['.'for j in range(i+n)] for i in range(n)]\na1=s[:n]\na2=s[n:3*n-2]\na3=s[3*n-2:4*n-4][::-1]\nfor i in range(n):\n    l[i][n-i-1]=a1[i]\nfor i in range(1,2*n-1):\n    l[n-1][i]=a2[i-1]\nfor i in range(1,n-1):\n    l[i][n+i-1]=a3[i-1]\nfor i in range(n):\n    print(''.join(l[i]))\n\n E 正文"},{"aid":"83521","title":"python-等腰三角形","date":"2022-02-05","likes":0,"views":1012,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-等腰三角形\n\n解题思路:\n从题目中我们知道0~9每个数字占一位。\n①先生成1~1000的数字字符串，（'123456789101112131415161718192021......'），这里记为A。\n②我们可以将三条边分开处理，通过观察图像规律：\n    左边所需要的字符串长度为n位，A中的下标对应为[0,n-1]。\n    底边所需要的字符串长度为2n-2位，A中的下标对应为[n,3n-3]。\n    右边所需要的字符串长度为n-2位，A中的下标对应为[3n-2,4n-5]。\n因此，我们可以分别将三条边需要的数字字符串从A中取出来，分别存放在字符串A1，A2，A3中，为了后续方便，我们将A3逆序。\n③按要求生成一个直角梯形的矩阵，初始用‘.’进行填充。\n④按照规律填充对应位的数字即可。\n\n![](https://blog.dotcpp.com/uploads/20220205/1644041190214392.png)\n\n注意事项:\n\n参考代码:\nn = int(input().strip())\nA= ''\nfor i in range(1,1000):\n    A = A + str(i)\nA1 = A[:n]                   #左边数字\nA2 = A[n:3*n-2]              #底边数字\ntemp = A[3*n-2:4*n-4]\nA3 = temp[::-1]              #右边数字\n\nR = [['.' for j in range(n+i)] for i in range(n)]  #初始化矩阵\n\nfor i in range(n):           #填充左边\n    R[i][n-1-i] = A1[i]\n\nfor i in range(2*n-2):       #填充底部\n    R[n-1][i+1] = A2[i]\n\nfor i in range(n-2):         #填充右边\n    R[1+i][n+i] = A3[i]\n\nfor i in range(n):\n    for j in range(n+i):\n        print(R[i][j],end='')\n    print()\n\n E 正文"},{"aid":"78181","title":"简单方法！字符串处理","date":"2021-04-02","likes":0,"views":881,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-等腰三角形\n\n解题思路:把要处理的数字全部都插入到字符串当中， 然后找规律， 进行输出。\n\n注意事项:详情都写在代码里\n\n参考代码:\n#includeusing namespace std;\n\ntypedef long long ll;\nconst int N = 1011;\nstring res = \"\", ans = \"\";//ans串没用到，忽略\nint n, num;\nint main() {\n\tcin >> n;\n\tint bot = 2 * n - 3;三角形底部的字符数，除了最边上的两个\n\tint top = 2 * n - 1;三角形左右边的字符数\n\tfor (int i = 1; i <= 3 * n; i++) res += to_string(i);//处理数字转为string类型，为什么是3 * n， 因为3*n肯定比三角形总字符数大啦，其实选什么数字都可\n\tint num = bot + top; //总数\n\tfor (int i = 1; i <= n-1; i++) cout << \".\";第一行 先输出点\n\tcout << 1 <<endl;先把1输出\n\tint ww = 4 * n - 2, dd = 1;//比如n是5， 那么第二行就是[1] . [15], 三行就是[2] . . [14],发现和为16 ww是什么？ 就是推导右侧边的数组索引的数字\n\t//找规律即可\n\tfor (int i = 2; i <= n-1; i++){\n\t\tfor (int j = 1; j <= n - i; j++) cout << \".\";\n\t\tcout << res[i-1] ;//左侧边\n\t\tfor (int j = 1; j <= dd; j++) cout << \".\";\n\t\tcout << res[ww - i - 1] <<endl;//右侧边\n\t\tdd += 2;//dd是点的数量，每次循环都加2.\n\t}\n\tfor (int i = n ; i <= ww-n; i++) cout << res[i - 1] ;两侧输出完毕， 输出底部， 取string串中间没输出的就行啦。\n\treturn 0;\n}\n\n E 正文"},{"aid":"77946","title":"2282: 蓝桥杯2018年第九届真题-等腰三角形（Python3）","date":"2021-03-26","likes":0,"views":1019,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-等腰三角形\n\n解题思路:\n利用标准库中的无限迭代器产生数字，然后根据计算的长度控制循环的结束\n\n注意事项:\n\n参考代码:\nfrom itertools import count\n\nn, last_index = int(input()), 0\ntemp, cycle = '', count(1)\nwhile len(temp) < 4 * n - 4:\n    temp += str(next(cycle))\ntemp = temp[:4 * n - 4]\nprint(((2 * (n - 2) + 2) // 2) * \".\" + temp[0])\nfor i in range(1, n - 1):\n    print(((2 * (n - 2) + 2) // 2 - i) * \".\" + temp[i] + \\\n          (2 * (i - 1) + 1) * \".\" + temp[-i])\n    last_index = i\nprint(temp[last_index + 1:-last_index:1])\n\n E 正文"},{"aid":"74881","title":"蓝桥杯2018年第九届真题-等腰三角形-题解（C语言代码）","date":"2021-01-06","likes":0,"views":2618,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-等腰三角形\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include <stdio.h>\nint n,a[1000][1000];\nint b[1500];\nint count=1,len=0,num=1;\nvoid getnum()\t//先求出要放的数\n{\n\tint j=0,i;\n\tfor (i=1;i<=500;i++)\n\t\t{\n\t\t\tnum=i;\n\t\t\tif(num<=9)\t//一位数\n\t\t\t\t{\n\t\t\t\t\tb[j]=num%10+1;\n\t\t\t\t\tj++;\n\t\t\t\t}\n\t\t\telse if(num>=10&&num<=99)//两位数\n\t\t\t\t{\n\t\t\t\t\tb[j]=num/10+1;\n\t\t\t\t\t\tj++;\n\t\t\t\t\tb[j]=num%10+1;\n\t\t\t\t\t\tj++;\n\t\t\t\t}\n\t\t\telse {\t\t//三位数\n\t\t\t\t\tb[j]=num/100+1;\n\t\t\t\t\t\tj++;\n\t\t\t\t\tb[j]=num%100/10+1;\n\t\t\t\t\t\tj++;\n\t\t\t\t\tb[j]=num%10+1;\n\t\t\t\t\t\tj++;\n\t\t\t\t}\n\t\t}\n\treturn ;\n}\nint main()\n{\n\tscanf(\"%d\",&n);\n\tgetnum();\n\tint i,j,index=0;\n\tlen=2*n-1;\n\tfor(j=n-1,i=0;j>=0;j--,i++)\t//左\n\t\t{\n\t\ta[i][j]=b[index];\n\t\tindex++;\n\t\t}\n\tfor(j=1,i--;j<len;j++)//下\n\t\t{\n\t\ta[i][j]=b[index];\n\t\tindex++;\n\t\t}\n\t\tj--;\n\tfor(i--,j--;i>=1;i--,j--)//右\n\t\t{\n\t\ta[i][j]=b[index];\n\t\tindex++;\n\t\t}\n\tfor(int x=0;x<n;x++)\n\t\t{\n\t\t\tfor(int y=0;y<n+x;y++)\n\t\t\t\tif(a[x][y]==0)\n\t\t\t\t\tprintf(\".\");\n\t\t\t\telse printf(\"%d\",a[x][y]-1);\n\t\t\tprintf(\"\\n\");\n\t\t}\n\t\treturn 0;\n}\n\n E 正文"}],"2283":[{"aid":"108792","title":"蓝桥2018省-使用并查集求最大环中的节点的数量","date":"2025-03-15","likes":1,"views":565,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-小朋友崇拜圈\n\n Server-side output Markdown text\n# 使用并查集寻找环\n**使用并查集来寻找环更加简单 只需要记住固定的板子即可**\n\n***思路*** 进行正常的并查集的时候 如果存在 find(x) == find(y）根结点（祖宗结点相同）即说明他们会形成一个环\n\n而以下的利用以下循环来求得环的结点的数量：\n\n```cpp\n\nwhile (value != x)\n{\n\tvalue = a[value - 1];\n\tcircleSize ++ ;\n}\n\n```\n\n然后每次更新最大环得结点得数量即可。\n\n#### Code:\n\n```cpp\n#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <queue>\n#include <deque>\n#include <unordered_map>\n#include <map>\n#include <cstring>\n#include <cmath>\n#include <unordered_set>\n#include <set>\n#include <utility>\n#include <climits>\n#include <iomanip>\n#include <stack>\n\n#define int long long\n#define PII pair<int, int>\n#define inf 0x3f3f3f3f3f3f3f3f\n#define all(v) v.begin() , v.end()\n\nusing namespace std;\nconst int N = 1e5 + 10;\nint p[N] ；\nint n , ans;\n\nint find(int x)\n{\n    if (x != p[x]) p[x] = find(p[x]);\n    return p[x];\n}\n\nvoid findCircle(vector<int> &a)\n{\n    for (int i = 1 ; i <= n ; i ++ ) p[i] = i;\n\n    for (int i = 1 ; i <= n ; i ++ )\n    {\n        int x = i , y = a[i - 1];\n\n        if (find(x) == find(y))\n        {\n            int circleSize = 1;\n            int value = y;\n            while (value != x)\n            {\n                value = a[value - 1];\n                circleSize ++ ;\n            }\n            ans = max(ans , circleSize);\n        }\n        else p[find(x)] = find(y);\n    }\n}\n\nvoid solve()\n{\n    cin >> n;\n    vector<int> a(n);\n    for (int i = 0 ; i < n ; i ++ ) cin >> a[i];\n\n    findCircle(a);\n\n    cout << ans << endl;\n}\n\nsigned main()\n{\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr), cout.tie(nullptr);\n\n    solve();\n    return 0;\n}\n\n```\n\n#### 完结撒花！\n\n E 正文"},{"aid":"104199","title":"2283: 蓝桥杯2018年第九届真题-小朋友崇拜圈","date":"2024-04-06","likes":0,"views":650,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-小朋友崇拜圈\n\n解题思路:dfs\n\n注意事项:一个人只能用一次\n\n参考代码:\n#include <iostream>\nusing namespace std;\nint num[100005];\nint flag[100005]={0};\nint tong[100005]={0};//是否被崇拜\nint ans=0,n;\nvoid dfs(int k,int x,int m){//k表示最开始的人，最后一个人崇拜的必须是他才能形成一个环\n\tif(k==num[x]){\n\t\tif(m>ans) ans=m;\n\t\treturn;\n\t}\n\tflag[x]=1;\n\tif(flag[num[x]]==0){\n\t\tdfs(k,num[x],m+1);\n\t}\n\tflag[x]=0;\n}\nint main()\n{\n\tcin>>n;\n\tfor(int i=1;i<=n;i++){\n\t\tcin>>num[i];\n\t\ttong[num[i]]=1;\n\t}\n\tfor(int i=1;i<=n;i++){\n\t\tif(tong[i]==0) continue;//没有崇拜自己的，就形不成一个环，直接跳过\n\t\tdfs(i,i,1);\n\t}\n\tcout<<ans;\n    return 0;\n}\n\n E 正文"},{"aid":"103394","title":"java--study||O.o","date":"2024-03-13","likes":0,"views":664,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-小朋友崇拜圈\n\n参考代码:\n\nimport java.util.Scanner;\n\npublic class Main\n{   static int n, arr[];\n\tpublic static void main(String[] args)\n\t{\tScanner scanner = new Scanner(System.in);\n\t\tn = scanner.nextInt();\n\t\tarr = new int[n + 1];\n\t\tfor(int i = 1; i <= n; i++)\n\t\t\tarr[i] = scanner.nextInt();\n\t\tscanner.close();\n\n\t\tint res = 0;\n\t\tvis = new int[n + 1];\n\t\tfor(int i = 0; i < n; i++)\n\t\t\tif(vis[i] == 0)//如果这个小朋友曾经打过标记，说明他所在的圈已经判断了\n\t\t\t{\tflag = 0;\n\t\t\t\tres = Math.max(res, dfs(i));\n\t\t\t}\n\t\tSystem.out.print(res);\n\t}\n\tstatic int vis[], flag;//标记，直接记长度\n\tstatic int dfs(int index)\n\t{\tflag++;\n\t\tif(vis[index] > 0)\n\t\t\treturn flag - vis[index];//圈长度\n\t\tvis[index] = flag;\n\t\treturn dfs(arr[index]);//去找index的崇拜小朋友\n\t}\n}\n\n E 正文"},{"aid":"98113","title":"蓝桥杯2018年第九届真题-小朋友崇拜圈(有向图强连通分量)","date":"2023-08-21","likes":0,"views":642,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-小朋友崇拜圈\n\n#include<bits/stdc++.h>\nusing namespace std;\n#define maxx 310000\nint a,n,anss;\nint ans[maxx];\nvector<int> G[maxx];\nint pre[maxx],lowlink[maxx],sccno[maxx],dfs_clock,scc_cnt;\nstack<int> S;\nvoid dfs(int u)\n{\n    pre[u]=lowlink[u]=++dfs_clock;\n    S.push(u);\n    for(int i=0;i<G[u].size();++i)\n    {\n        int v=G[u][i];\n        if(!pre[v])\n        {\n            dfs(v);\n            lowlink[u]=min(lowlink[u],lowlink[v]);\n        }\n        else if(!sccno[v])\n        {\n            lowlink[u]=min(lowlink[u],pre[v]);\n        }\n    }\n    if(lowlink[u]==pre[u])\n    {\n        scc_cnt++;\n        for(;;)\n        {\n            int x=S.top();S.pop();\n            sccno[x]=scc_cnt;\n            if(x==u) break;\n        }\n    }\n}\nint main()\n{\n  cin>>n;\n  for(int i=1;i<=n;++i)\n  {\n    cin>>a;\n    G[a].push_back(i);\n\n  }\n  for(int i=1;i<=n;++i)\n  if(pre[i]==0) dfs(i);\n  for(int i=1;i<=n;++i) ++ans[sccno[i]];\n  for(int i=1;i<=n;++i) anss=max(anss,ans[i]);\n  cout<<anss;\n\n}\n\n E 正文"},{"aid":"95666","title":"纯纯地dfs暴力就完了","date":"2023-04-05","likes":0,"views":669,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-小朋友崇拜圈\n\n Server-side output Markdown text\n给每个小朋友打上标记，圈的长度就是当前标记-小朋友的标记\n```cpp\n#include<bits/stdc++.h>\nusing namespace std;\n#define ll long long\nconst int N=100005;\nint mp[N],n,vis[N],cut,mx=-1;\nint dfs(int x){\n\t++cut;\n    if(vis[x]) return cut-vis[x];\n    vis[x]=cut;\n\treturn dfs(mp[x]);\n}\nint main() {\n\tcin>>n;\n\tfor(int i=1;i<=n;i++){\n\t\tcin>>mp[i];\n\t}\n\tfor(int i=1;i<=n;i++){\n\t\tif(vis[i]==0){\n\t\t\tcut=0;\n\t\t\tmx=max(dfs(i),mx);\n\t\t}\n\t}\n\tcout<<mx;\n\treturn 0;\n}\n```\n\n E 正文"}],"2284":[{"aid":"95125","title":"蓝桥杯2018年第九届真题-耐摔指数","date":"2023-03-22","likes":0,"views":1015,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-耐摔指数\n\n解题思路:\n\n注意事项:\n\n参考代码:\npackage dotcpp.二分;\n//x星球的居民脾气不太好，但好在他们生气的时候唯一的异常举动是：摔手机。\n//各大厂商也就纷纷推出各种耐摔型手机。x星球的质监局规定了手机必须经过耐摔测试，\n// 并且评定出一个耐摔指数来，之后才允许上市流通。\n//x星球有很多高耸入云的高塔，刚好可以用来做耐摔测试。塔的每一层高度都是一样的，\n// 与地球上稍有不同的是，他们的第一层不是地面，而是相当于我们的2楼。\n//如果手机从第7层扔下去没摔坏，但第8层摔坏了，则手机耐摔指数=7。\n//特别地，如果手机从第1层扔下去就坏了，则耐摔指数=0。\n//如果到了塔的最高层第n层扔没摔坏，则耐摔指数=n\n//为了减少测试次数，从每个厂家抽样3部手机参加测试。\n//如果已知了测试塔的高度，并且采用最佳策略，\n// 在最坏的运气下最多需要测试多少次才能确定手机的耐摔指数呢？\n//输入\n//输入数据，一个整数n（3<n<10000）,表示测试塔的高度。\n//输出\n//输出一个整数，表示最多测试多少次。\n//样例输入\n//例如：\n//输入：\n//3\n//再例如：\n//输入：\n//7\n/*\n//建议先参考一下算法设计与分析第2版（屈婉玲）第二章的课后习题2.30\nF2[n]含义为两部手机测试n次时可以尝试出的最大楼层数\nF3[n]含义为两部手机测试n次时可以尝试出的最大楼层数\n思路：首先考虑测试n次能支持的最大层数的关系。\n首先考虑只有一部手机的时候，因为只有一部手机所以我们只能从第一层开始，一层一层的往上试i\n因此次数与最大层数的关系为：F1(n)=n;\n然后我们考虑有两部手机的时候，因为题目说了是运气最差的时候，采取最佳方案所以我们首先从最理想位置（第根号n下取整层）下坠，\n举个例子：塔10层，当你在5楼下坠时，裂开了就试1，2，3，4 。没开就2部手机继续试6-10 这样运气不好是5次\n但 4 楼下坠 裂开试1，2，3 。没开2部手机继续试5-10 运气不好是4次\n两部手机试6-10，共5层楼。5-10，共6层。与F2(n-1)形成递推公式\n我们扔第一部手机有两种情况\n（1）手机碎了，那你现在就只有一步手机了，那就由和只有一部手机时候一样了，不过此时，你已经扔过一次了所以：\nF1(n-1)+1 多尝试一次楼层\n（2）手机，没碎，你现在有两部手机，n-1次测试次数 ：\nF2(n-1)\n总的来看，当你有两部手机的时候。\n无论裂开与否，此时最多只要尝试\nF2(n)=F2(n-1)+1+F1(n-1)\n然后就简单了，当我们有三部手机的时候，你先扔一部，又是有两种可能，所以：\nF3(n)=F3(n-1)+F2(n-1)+1\n* */\nimport java.util.Scanner;\npublic class 耐摔指数 {\n    static int f2[]=new int[1000];\n    static int f3[]=new int[1000];\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int altitude = scanner.nextInt();\n        int i = 0;\n        while (f3[i] < altitude) {\n            i++;\n            f2[i] = f2[i - 1] + i;//这里i本身就++了，所以不用加一了\n            f3[i] = f3[i - 1] + f2[i - 1] + 1;\n        }\n        System.out.println(i);\n    }\n}\n\n E 正文"},{"aid":"86298","title":"蓝桥杯2018年第九届真题-耐摔指数 Dp模拟过程，详细注释","date":"2022-04-06","likes":0,"views":937,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-耐摔指数\n\n Server-side output Markdown text\n动态规划模拟试的过程，参考了别人的想法\n转态方程很不容易想到，**考虑两种情况，手机碎或者没碎，如果碎了，那么手机数减一，而且要从当前楼的下一层开始试，如果没碎，那么当前手机数不变，但还得挨个试剩下来的楼层，需要注意的是，不管当前的手机碎没碎，本次都算一次测试**\n有一说一，真不好想orz，怎么想出来的啊！！！\n代码如下：\n```cpp\n#include<iostream>\n#include<algorithm>\nusing namespace std;\nint dp[4][10005];//dp[i][j]表示用i部手机试j层楼需要的次数\nint n;\nint main()\n{\n\tcin >> n;\n\tfor (int i = 1; i <= 3; i++)\n\t\tfor (int j = 1; j <= n; j++)\n\t\t\tdp[i][j] = j;//初始化，不在最佳策略下，不管用多少部手机试j层楼最多都需要j次\n\tfor(int i=2;i<=3;i++)\n\t\tfor(int j=1;j<=n;j++)\n\t\t\tfor (int k = 1; k < j; k++)\n\t\t\t{\n\t\t\t\tdp[i][j] = min(dp[i][j],max(dp[i][j-k],dp[i-1][k-1])+1);//两种情况,第一种在k层没有摔坏，那么在最坏情况下接下来还要再做j-k次，状态转移到dp[i][j-k]\n\t\t\t\t//第二种，在k层摔坏了，现在则只剩下i-1部手机，要拿这i-1部手机到k-1层试，状态转移到dp[i-1][k-1]\n\t\t\t\t// 因为是最坏情况所以要取两者之间的大者\n\t\t\t\t//注意试的时候不管碎没碎，本身也算一次，所以两者中最大值要加一，min()指在最佳策略下\n\t\t\t}\n\tcout << dp[3][n];\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"86238","title":"蓝桥杯2018年第九届真题-耐摔指数","date":"2022-04-05","likes":0,"views":1046,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-耐摔指数\n\n Server-side output Markdown text\n```cpp\n//打表发现后面可以利用前面——>动态规划\n//由手机部数和层数两个变量决定测试次数结果——>动态规划\n\n#include<iostream>\n#include<cmath>\n\nusing namespace std;\nconst int N = 10000;\nint f1[N + 1], f2[N + 1], f3[N + 3];//分别表示有1，2，3部手机\nint n;\nint main() {\n\tcin >> n;\n\t//只有一部手机的情况，只能从第一层开始扔，所以测试次数和层数相同\n\tfor (int i = 1; i <= n; i++) {\n\t\tf1[i] = i;\n\t}\n\t//有两部手机，依此生成共i层的测试次数,从前往后递推生成\n\tfor (int i = 1; i <= n; i++) {\n\t\tint ans = 0x3f3f3f;\n\t\t//第一部手机在第j层(1~i)扔下\n\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t//情况1：该手机完好，则还有两部手机，剩余i-j层需要测试(因为是递推上来的，前面层数肯定有结果了，所以只要看后面的)\n\t\t\t//情况2：该手机坏了，则还有一部手机，剩余j-1层需要测试(这一层坏了，那么就去测试下一层)\n\t\t\tint _max = 1 + max(f2[i - j], f1[j - 1]);//取max就是运气最坏，1是该次测试次数\n\t\t\tans = min(_max, ans);//取min就是最佳策略\n\t\t}\n\t\tf2[i] = ans;\n\t}\n\t//有三部手机，依此生成共i层的测试次数,从前往后递推生成\n\tfor (int i = 1; i <= n; i++) {\n\t\tint ans = 0x3f3f3f;\n\t\t//第一部手机在第j层(1~i)扔下\n\t\tfor (int j = 1; j <= i; j++) {\n\t\t\t//情况1：该手机完好，则还有三部手机，剩余i-j层需要测试(因为是递推上来的，前面层数肯定有结果了，所以只要看后面的)\n\t\t\t//情况2：该手机坏了，则还有两部手机，剩余j-1层需要测试(这一层坏了，那么就去测试下一层)\n\t\t\tint _max = 1 + max(f3[i - j], f2[j - 1]);//取max就是运气最坏，1是该次测试次数\n\t\t\tans = min(_max, ans);//取min就是最佳策略\n\t\t}\n\t\tf3[i] = ans;\n\t}\n\tcout << f3[n] << endl;\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"82263","title":"2284-耐摔指数(动态规划)-c语言","date":"2021-12-29","likes":0,"views":1661,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-耐摔指数\n\n#include<stdio.h>\n#define M 20000\nint max(int a,int b)\n{\n\treturn a>b?a:b;\n}\nint min(int a,int b)\n{\n\treturn a>b?b:a;\n}\nint main()\n{\n\tint N;\n\tscanf(\"%d\",&N);\n\tint dp[10][M]= {0};\n\tint m = 3, i,  j,  k;\n\tfor(j = 1; j <= N; j++)\n\t{\n\t\tdp[1][j] = j;\n\t}\n\tfor(i = 2; i <= m; i ++)\n\t{\n\t\tfor(j = 1; j <= N; j++)\n\t\t{\n\t\t\tdp[i][j] = j;\n\t\t\tfor(k = 1; k <= j; k++)\n\t\t\t{\n\t\t\t\tint num = max(1+dp[i-1][k-1], 1+dp[i][j-k]);\n\t\t\t\tdp[i][j] = min(dp[i][j], num);\n\t\t\t}\n\t\t}\n\t}\n\tprintf(\"%d\", dp[m][N]);\n\treturn 0;\n}解题思路:\n\n注意事项:\n\n参考代码:\n\n E 正文"},{"aid":"72343","title":"蓝桥杯2018年第九届真题-耐摔指数-题解（C++代码）","date":"2020-08-26","likes":0,"views":2897,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-耐摔指数\n\n解题思路:    考虑测试n次能支持的最大层数的关系。\n        首先考虑只有一部手机的时候，因为只有一部手机所以我们只能从第一层开始，一层一层的往上试\n        因此次数与最大层数的关系为：F1(n)=n;\n        然后我们考虑有两部手机的时候，因为题目说了是运气最差的时候，所以我们首先从哪里开始扔第一个手机也就没什么区别了，我们扔第一部手机有两种情况\n        （1）手机碎了，那你现在就只有一步手机了，那就由和只有一部手机时候一样了，不过此时，你已经扔过一次了所以：\n                F1(n-1)+1\n        （2）手机，没碎，你现在有两部手机，n-1次测试次数 ：\n                F2(n-1)\n\n        总的来看，当你有两部手机的时候\n        F2(n)=F2(n-1)+1+F1(n-1)\n\n        然后就简单了，当我们有三部手机的时候，你随便先扔一部，又是有两种可能，所以：\n        F3(n)=F3(n-1)+F2(n-1)+1\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n\nint f2[105], f3[105];\n\nint main() {\n\tint n; cin >> n;\n\n\tint i = 0;\n\twhile(f3[i] < n){\n\t\ti++;\n\t\tf2[i] = f2[i-1] + i;//这里i本身就++了，所以不用加一了\n\t\tf3[i] = f3[i-1] + f2[i-1] + 1;\n\t}\n\tcout << i << endl;\n\n\treturn 0;\n}\n\n E 正文"}],"2285":[{"aid":"98114","title":"蓝桥杯2018年第九届真题-螺旋折线","date":"2023-08-21","likes":0,"views":657,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-螺旋折线\n\n解题思路:\n以坐标绝对值最大的划分正方形个数，之前的都是正方形\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n#define int long long\nint x,y,q,ans;\nint main()\n{\n  cin>>x>>y;\n  int q=max(abs(x),abs(y));\n  ans=1+4*(q*(q-1));\n  if(x==-q&&y==-q) ans=ans+8*q-1;\n  else if(x==-q) ans=ans+(y+q-1);\n  else if(y==q) ans=ans+(2*q-1+x+q);\n  else if(x==q) ans=ans+(4*q-1+q-y);\n  else if(y==-q) ans=ans+(6*q-1+q-x);\n  cout<<ans;\n}\n\n E 正文"},{"aid":"95194","title":"蓝桥杯2018年第九届真题-螺旋折线 新手代码","date":"2023-03-23","likes":0,"views":554,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-螺旋折线\n\n解题思路:\n\n注意事项: 注意右上顶点的步数\n（1，1）4（2，2）16（3，3）36\n\n参考代码:\npackage dotcpp.数学;\n\nimport java.util.Scanner;\n\npublic class 螺旋折线 {\n    public static void main(String[] args) {\n        Scanner scanner=new Scanner(System.in);\n        long X=scanner.nextLong();\n        long Y=scanner.nextLong();\n        long Pos=Math.max(Math.abs(X),Math.abs(Y));\n        long step=Pos*Pos*4;\n        if(X/Pos==1){\n            System.out.println(step+Pos-Y);\n        }\n        else if(X/Pos==-1){\n          System.out.println(step-2*Pos-(Pos-Y));\n        }\n        else if(Y/Pos==1)\n        {\n           System.out.println(step-(Pos-X));\n        }\n        else if(Y/Pos==-1){\n            System.out.println(step+2*Pos+(Pos-X));\n        }\n    }\n}\n\n E 正文"},{"aid":"90728","title":"简单的数学题","date":"2022-10-23","likes":0,"views":541,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-螺旋折线\n\n解题思路:\n\n注意事项:\n\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\ntypedef long long ll;\nll x,y;\nint main(){\n    scanf(\"%lld%lld\",&x,&y);\n    ll r=max(abs(x),abs(y));\n    if(x==r){\n        printf(\"%lld\",4*r*r+r-y);\n    }\n    else if(y==-r){\n        printf(\"%lld\",4*r*r+2*r+r-x);\n    }\n    else if(x==-r){\n        printf(\"%lld\",4*r*r-2*r-(r-y));\n    }\n    else if(y==r){\n        printf(\"%lld\",4*r*r-(r-x));\n    }\n    //system(\"pause\");\n    return 0;\n}\n\n E 正文"},{"aid":"86527","title":"蓝桥杯2018年第九届真题-螺旋折线","date":"2022-04-09","likes":0,"views":803,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-螺旋折线\n\n Server-side output Markdown text\n\n```cpp\n#include<iostream>\n#include<cmath>\nusing namespace std;\nlong long x, y;\nlong long ans;\nlong long n;\nint main()\n{\n\tcin >> x >> y;\n\tif (abs(x) <= y&&y>0)//上\n\t{\n\t\tn = y;\n\t\tans = (2 * n + 1) * 2 * n - 2 * n - (n - x);\n\t}\n\telse if (x > 0 && abs(y) <= x)//右\n\t{\n\t\tn = x;\n\t\tans = (2 * n + 1) * 2 * n - abs(-n - y);\n\t}\n\telse if (y <= 0 && x + 1 >= y && abs(x) <= abs(y))//下\n\t{\n\t\tn = abs(y);\n\t\tans = (2 * n - 1) * 2 * (n - 1) + (n - 1) - x;\n\t}\n\telse if (x < 0 && y >= x + 1 && y <= -x)//左\n\t{\n\t\tn = abs(x) ;\n\t\tans = (2 * n-1) * 2 * (n-1) + abs(x)+abs(x)-1 + y - (x + 1);\n\t}\n\tcout << ans;\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"85787","title":"蓝桥杯2018年第九届真题-螺旋折线pyhton","date":"2022-03-27","likes":0,"views":822,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-螺旋折线\n\n Server-side output Markdown text\n思路来源：https://www.bilibili.com/video/BV1dD4y1m7Cv?share_source=copy_web\n\n    x,y = map(int,input().split())\n    count = max(abs(x),abs(y))\t\t#点所在方形层数由x，y坐标中绝对值最大的决定\n\n    #用等差数列求和公式求解当前方形内部的所有含有方形的总边数\n    inside = 8*(count-1)+(count-1)*(count-2)*8//2 #若用循环会超时\n\n\t#求当前点所在方形从起点开始经过的边数\n    if y>0 and y==count:\t#点在方向上横边时\n            l = 3*count+x\n    elif y<0 and abs(y)==count:\t#点在方形下横边时\n            l = 7*count-x\n    elif x>0 and x==count:\t\t#点在方形右竖边时\n            l = 5*count-y\n    elif x<0 and abs(x)==count:\t#点在方形左竖边时\n            l = count+y\n\n    print(l+inside)\t\t\t#输出结果\n\n E 正文"}],"2286":[{"aid":"98115","title":"蓝桥杯2018年第九届真题-堆的计数(递推)","date":"2023-08-21","likes":0,"views":858,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-堆的计数\n\n解题思路:\n采用递推的思想，利用dp[i]记录i排列时可以构造出合法的堆的情况数，由于堆只要求数字的相对大小，故不相等的n个数字可以构造出堆的个数是一致的，同时最小的数字一定在堆顶，(因为如果最小的数字不在堆顶，堆顶的数字就会比它大，堆不合法),对于n个数字的堆，我们这样构造，将最小数字放在堆顶，由于是完全二叉树，剩下n-1个数字可以计算出左右子树的数字个数，记左子树当前需要k个数字，基于上面说的，我们随意的选择k个数字，其构造出的左子树堆个数都是一致，剩下的作为右子树堆个数，依据乘法原理则有dp[i]=dp[k]*dp[i-1-k]*c(i,k)。\n利用费马小定理优先处理出阶乘和其逆元，然后利用费马小定理计算c(i,k)。\n注意事项:\n递推边界，模运算，逆元使用快速幂。复杂度O(nlogn),主要在于逆元的计算。\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n#define maxx 310000\n#define mod 1000000009\n#define int long long\nint jc[maxx];\nint jcf[maxx];\nint n,x1,x2;\nint dp[maxx];\nint poww(int i,int j) //快速幂\n{\n  if(j==0) return 1;\n  if(j==1) return i%mod;\n  int q=poww(i,j/2);\n  if(j%2==0) return (q*q)%mod;\n  else return ((q*q)%mod*i%mod)%mod;\n}\nvoid starting()\n{\n  jc[0]=jcf[0]=1;\n  for(int i=1;i<=n;++i) jc[i]=(jc[i-1]*i)%mod;\n  for(int i=1;i<=n;++i) jcf[i]=(jcf[i-1]*poww(i,mod-2))%mod;\n}\nint C(int i,int j) //计算组合数\n{\n  int q=(jc[i]*jcf[j])%mod;\n  return (q*jcf[i-j])%mod;\n}\nsigned main()\n{\n  cin>>n;\n  starting();\n  dp[0]=dp[1]=1;\n  for(int i=2;i<=n;++i)\n  {\n    int zs=pow(2,(int)log2(i))-1;\n    int sy=i-zs;\n    x1=x2=(zs-1)/2;\n    x1+=min((zs+1)/2,sy);\n    x2+=max((int)0,sy-(zs+1)/2);\n    dp[i]=((dp[x1]*dp[x2])%mod*C(i-1,x1))%mod;\n  }\n cout<<dp[n];\n}\n\n E 正文"},{"aid":"73047","title":"蓝桥杯2018年第九届真题-堆的计数-题解（Java代码）","date":"2020-10-06","likes":0,"views":1592,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-堆的计数\n\n Server-side output Markdown text\n```\nimport java.util.Scanner;\n\npublic class Main{\n\tprivate static final int MOD = 1000000009;\n\tprivate static int N;\n\tprivate static int[] size;\t//记录每个节点的size\n\tprivate static long[] jie;\t//记录1~N的阶乘\n\tprivate static long[] ni;\t//记录1~N的阶乘的逆元\n\n\tpublic static void main(String[] args) {\n\t\tScanner sc = new Scanner(System.in);\n\t\tN = sc.nextInt();\n\t\tsize = new int[N + 1];\n\t\tjie = new long[N + 1];\n\t\tni = new long[N + 1];\n\t\tinitSize();\n\t\tinitJie();\n\t\tSystem.out.println(dp());\n\n\t\tsc.close();\n\t}\n\tprivate static long dp() {\n\t\tlong[] d = new long[N + 1];\t//d[i]表示的是i号节点作为根,小根堆的种数\n\t\tfor(int x = N; x >= 1; x--) {\n\t\t\tif(2 * x + 1 <= N) {\n\t\t\t\td[x] = c(size[x] - 1, size[2 * x]) * d[2 * x] % MOD * d[2 * x + 1] % MOD;\n\t\t\t}else if(2 * x <= N) {\n\t\t\t\td[x] = c(size[x] - 1, size[2 * x]) * d[2 * x] % MOD;\n\t\t\t}else {\n\t\t\t\td[x] = 1;\n\t\t\t}\n\t\t}\n\t\treturn d[1];\n\t}\n\tprivate static void initJie() {\n\t\tjie[0] = 1;\n\t\tni[0] = 1;\n\t\tfor(int i = 1; i <= N; i++) {\n\t\t\tjie[i] = jie[i - 1] * i % MOD;\n\t\t\tni[i] = qpow(jie[i], MOD - 2);\n\t\t}\n\t}\n\tprivate static long qpow(long a, int n) {\n\t\tif(a == 0) {\n\t\t\treturn 0;\n\t\t}\n\t\tlong ans = 1;\n\t\tlong x = a;\n\t\twhile(n > 0) {\n\t\t\tif((n & 1) == 1) {\n\t\t\t\tans = ans * x % MOD;\n\t\t\t}\n\t\t\tn >>= 1;\n\t\t\tx = x * x % MOD;\n\t\t}\n\t\treturn ans;\n\t}\n\tprivate static void initSize() {\n\t\tfor(int i = N; i >= 1; i--) {\n\t\t\tsize[i] = (2 * i <= N ? size[2 * i] : 0) + (2 * i + 1 <= N ? size[2 * i + 1] : 0) + 1;\n\t\t}\n\t}\n\tprivate static long c(int n, int r) {\n\t\treturn jie[n] * ni[r] % MOD * ni[n-r] % MOD;\n\t}\n}\n```\n\n E 正文"}],"2287":[{"aid":"103378","title":"java--study||O.o","date":"2024-03-13","likes":0,"views":546,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-缩位求和\n\n参考代码:\n\nimport java.math.BigInteger;\nimport java.util.Scanner;\n\npublic class Main\n{   public static void main(String[] args)\n\t{\tScanner scanner = new Scanner(System.in);\n\t\tString s = scanner.next();\n\t\tString res = \"\";\n\t\twhile(s.length() > 1)\n\t\t{\tBigInteger sum = new BigInteger(\"0\");\n\t\t\tfor(int i = 0; i < s.length(); i++)\n\t\t\t{\tint t = s.charAt(i) - '0';\n\t\t\t\tsum = sum.add(new BigInteger(\"\" + t));\n\t\t\t}\n\t\t\ts = sum.toString();\n\t\t\tres = sum.toString();\n\t\t}\n\n\t\tSystem.out.print(res);\n\t}\n}\n\n E 正文"},{"aid":"102553","title":"蓝桥杯2018年第九届真题-缩位求和(Java)","date":"2024-02-06","likes":0,"views":539,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-缩位求和\n\n Server-side output Markdown text\n```java\nimport java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n\t\tScanner sc = new Scanner(System.in);\n        String str = sc.next();\n        int sum = 0;\n        while (str.length()!=1){\n            sum = 0;\n            for (int i = 0; i < str.length(); i++) {\n                sum+=str.charAt(i)-'0';\n            }\n            str = sum+\"\";\n        }\n        System.out.println(sum);\n\t}\n}\n```\n\n E 正文"},{"aid":"95635","title":"蓝桥杯2018年第九届真题-缩位求和","date":"2023-04-05","likes":0,"views":614,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-缩位求和\n\n解题思路:\n\n注意事项:\n\n参考代码:\nn = int(input())\nwhile len(str(n))!= 1:\n    n = sum(int(i) for i in str(n))\nprint(n)\n\n E 正文"},{"aid":"95575","title":"第一个pyAC 五行秒杀","date":"2023-04-03","likes":0,"views":643,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-缩位求和\n\n解题思路:\n\n注意事项:\n\n参考代码:\nn=int(input())\nwhile len(str(n))!=1:\n\n    x=sum(list(map(int,str(n))))\n\n    n=x\nprint(x)\n\n E 正文"},{"aid":"94230","title":"缩位求和C++非递归写法","date":"2023-02-23","likes":0,"views":672,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-缩位求和\n\n解题思路:\n思路很简单，难点就是要读懂题和清楚字符串与数字相互转换的语法。\n1 接收字符串S。\n2 建立循环，循环内容是： 1 将字符串的每一个值都转换为数字并相加得到sum。2 sum转换为新的字符串S。循环退出条件是sum的值比10小。\n3 循环结束后输出sum值。\n注意事项:\n无\n参考代码:\n#include<iostream>\nusing namespace std;\nint main()\n{\n    string S,temp;\n    cin>>S;\n    int sum;\n    do{\n        sum = 0;\n        for(int i=0 ; i<S.length() ; i++){\n            temp = S[i];\n            sum+=stoi(temp); //字符串转整型数字\n            }\n        S = to_string(sum); //整型数字转字符串\n    }while(sum >= 10);\n    cout<<sum;\n    return 0;\n}\n\n E 正文"}],"2288":[{"aid":"107051","title":"蓝桥杯2018年第九届真题-约瑟夫环-题解(C++代码)简单理解的进一步解释","date":"2024-11-10","likes":0,"views":799,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-约瑟夫环\n\n解题思路:大佬的代码逻辑太强，对此作进一步的解释说明\n此代码运用的其实是一种从后往前倒推的思想，我们先假设最后一个人的位置为0，即s=0,所以s+m即为倒数第二个人的报数位置，以此类推，直到推出第一个人的报数位置，同时，这种方法的妙处在于它利用了报数问题的对称性和周期性，即我们所推出的第一个人所在的位置即为最后所能留在圈子里的位置，因此这个位置也是我们所希望求的最后一个人的位置，最后因为我们报数是从1开始的，所以最后输出s的时候加1（即s+1)。\n\nfor循环中i之所以从2开始是因为s+m是第二个人的报数位置，由此倒退应该除2保证s是圈子内的数。\n注意事项:\n以上论述仅为个人观点，如有问题，多多指正。\n参考代码:\n\n#include<iostream>\n#include<cstring>\nusing namespace std;\nint main() {\n    int n, m, s=0, i;\n    cin >> n >> m;\n    for (i = 2; i <= n; i++) {\n        s = (s + m) % i;\n    }\n    cout << s+1 << endl;\n    return 0;\n}\n\n E 正文"},{"aid":"103980","title":"2288: 蓝桥杯2018年第九届真题-约瑟夫环","date":"2024-03-29","likes":0,"views":683,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-约瑟夫环\n\n Server-side output Markdown text\n    //假设删除一个人之后，我们对剩余的玩家重新编号\n\t//一开始编号为：1,2,...,m-1,m,m+1,...,n\n\t//将编号为m的玩家删除之后,编号变成：\n\t//...,n-2,n-1,1,2,...\n\t//删除前编号————删除后编号\n\t//m-1————n-2\n\t//m-2————n-1\n\t//m————无（被删除）\n\t//m+1————1\n\t//m+2————2\n\t//......\n\t//删除前与删除后对应关系为：old=(new+m-1)%n+1\n\t#include<iostream>\n    using namespace std;\n    int f(int n,int m){\n        return n==1?1:(f(n-1,m)+m-1)%n+1;\n    }\n    int main()\n    {\n        int n,m;\n        cin>>n>>m;\n        cout<<f(n,m)<<endl;\n        return 0;\n    }\n\n E 正文"},{"aid":"95367","title":"迭代解约瑟夫环","date":"2023-03-29","likes":0,"views":804,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-约瑟夫环\n\n解题思路:此题采用迭代来写，相比于递归来说，使用迭代速度更快，空间浪费更少\n\n注意事项:时间复杂度为O(n)，是递归的最终简化简直没有弱点，又快有不浪费空间\n参考代码:\n#include<stdio.h>\nint cir(int n,int m)\n{\n\tint p=0;\n\tfor(int i=2;i<=n;i++)\n\t{\n\t\tp=(p+m)%i;\n\t}\n\treturn p+1;\n}\n\nint main()\n{\n\tint m,n;\n\tscanf(\"%d %d\",&n,&m);\n\tprintf(\"%d\",cir(n,m));\n\treturn 0;\n}\n\n E 正文"},{"aid":"94287","title":"Python递推解决约瑟夫环","date":"2023-02-25","likes":0,"views":564,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-约瑟夫环\n\n解题思路:\n\n注意事项:\n\n参考代码:\nn,k=map(int,input().split())\na=list(range(1,n+1))\ns=0\nfor i in range(2,n+1):\n    s=(s+k)%i\nprint(s+1)\n\n E 正文"},{"aid":"78165","title":"2288: 蓝桥杯2018年第九届真题-约瑟夫环（Python3）","date":"2021-04-01","likes":0,"views":1177,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-约瑟夫环\n\n解题思路:\n思路同2254\n参考：https://zhuanlan.zhihu.com/p/133428674\n\n注意事项:\n\n参考代码:\nn, m = map(int, input().strip().split())\nres = [0, 0]\nres.extend((res[i - 1] + m) % i for i in range(2, n + 1))\nprint(res[-1] + 1)\n\n E 正文"}],"2289":[{"aid":"98119","title":"蓝桥杯2018年第九届真题-自描述序列(二分)","date":"2023-08-22","likes":0,"views":884,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-自描述序列\n\n解题思路:\n如果依照题意直接模拟会超时，只能通过30%的测试点。\n没有找到明显的数学规律，我们试图改进模拟方案。\n我们发现直接的模拟方案有一个缺陷，大量重复的数字占据了数组，我们改进此种方案，仅仅all数组记录下标的数字在G序列中的开始出现位置的下标，并且有如下递推方程all[i]=all[i-1]+k(all[k]<=i且all[k+1]>=i) ,具体方程的实现:使用noww记录当前的下标位置,ct记录超越此下标的个数，当ct大于all[noww+1]-all[noww]时将noww加一,ct置为0，依照此方法模拟后，遍历数组all,找到满足all[k]<=n且all[k+1]>=n)的k，依照此方法模拟后，可以通过70%的测试点。\n注意到，当模拟完毕后,noww并未到达数组最末尾处，这说明我们还可以用noww继续计算数组后的元素，具体实现方法为，我们首先处理ct,将ct置为最大后，再将noww加一，ct清零，此方案进行完毕后发现得到的元素已经大于等于n,那么我们需要二分寻找第一个大于n的ct,找到后减1即为最后一个小于等于n的ct,将先前的数组长度与ct相加即为答案;若元素小于n，我们先移动noww,同时更新数组的元素，更新策略为，增加noww*(all[noww+1]-all[noww])，若我们在更新过程中找到发现当前元素小于等于n,而后一个大于n,我们停止更新noww,利用二分寻找出第一个大于n的ct,找到后减1即为最后一个小于等于n的ct,将all[noww]与ct和作为答案输出。这样可以通过全部测试点。\n注意事项:\n数组长度的选取尽量偏大，选择2000000可以承受大约10^16大小的n的结果计算。\n代码时间复杂度在于循环的次数，二分是对数级别复杂度，模拟复杂度线性。\n实际上第二个改进对n的大小增幅比较明显，在第二个改进前，第一种改进在数组长度取到千万级别时也只能计算10^10大小的n的结果，而改进后仅仅百万级别的长度就可以计算10^16大小的n。\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n#define maxx 2000000\n#define int long long\nint ans,n,q,noww,ct;\nint all[maxx];\nint erfen(int l,int r)\n{\n   while(l<r)\n   {\n    int mid=(l+r)/2;\n    if(q+mid*noww<=n) l=mid+1;\n    else r=mid;\n   }\n   if(q+l*noww==n) return l;\n   else return l-1;\n}\nsigned main()\n{\n  cin>>n;\n  all[1]=1,all[2]=2;\n   ct=0,noww=2;\n  for(int i=3;i<=maxx;++i)\n   {\n     all[i]=all[i-1]+noww;\n     ++ct;\n     if(ct>=all[noww+1]-all[noww]) {++noww;ct=0;}\n   }\n\n   for(int i=1;i<=maxx;++i) if(all[i]<=n&&all[i+1]-1>=n) ans=i;\n\n   if(ans==0)\n   { q=all[maxx];\n    if(q+(all[noww+1]-all[noww]-ct)*noww>=n)\n    {\n      ans=maxx+erfen(1,all[noww+1]-all[noww]-ct);\n    }\n    else\n    {\n      q=q+(all[noww+1]-all[noww]-ct)*noww;\n      ++noww;ct=0;\n       for(int i=noww;i<maxx;++i)\n       {\n         if(q<=n&&q+i*(all[i+1]-all[i])>=n) break;\n         q=q+i*(all[i+1]-all[i]);\n         ++noww;\n       }\n       ans=all[noww]+erfen(1,all[noww+1]-all[noww]);\n    }\n   }\n\n   cout<<ans;\n\n}\n\n E 正文"},{"aid":"72879","title":"蓝桥杯2018年第九届真题-自描述序列-题解（C++代码）S","date":"2020-09-28","likes":0,"views":1639,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-自描述序列\n\n解题思路:\nS\n第一种思路，就是暴力求解，根据题目给出的规律，很容易用O(n)的时间求出1*10^6的数据，这样就已经获得30%的分数了，再往后就会超时。\n第二种思路，g[]数据表示相应的下标出现的次数，那我们可以对g[]数组求和。在求和的过程中判断求出的与目标数据的相比的大小。如果累加的和已经大于目标数据n，则求解的数字就是当前的i,这一部分核心代码如下：\n for(int i=1;i<=1000000;i++){\n    s+=g[i];\n    if(s>=n)\n        cout<<i;\n\t}\n但是这一种方法需要刚才第一种方法提供的数据，因此计算出的数据范围受第一种是方法范围的影响，只能完成10^9左右的数据。也就是70%的数据。\n第三种，因为第i个数据会在g[]数组中出现g[i]次，那么那么就相当于在g[]数组中会出现g[i]段长度为i且这i个数字相等的数字段，这样的话，就可以根据n在那一个数字段中求解。实现代码如下：\n for(int i=1;;i++){\n\t\ts+=i*(LL)g[i];\n    if(s>=n){\n        .....\n\n    }\n\t}\n如果将n确定在第i个数据段，那么需要将前i-1个数据段包含的数据相加。每个数据段包含g[]数据，则相当对数组g前i-1项求和。\nn在第i个数据段中，是第n-m个数字。在第i个段中，每一个数据会重复i次。那么n-m就是在这个段中的位置就是roundup(（n-m）/i)。因为在c++中没有向上取整，但是有个取整公式roundup((n-m)/i)==rounddown((n-m+i-1)/i).核心代码如下：\n for(int i=1;;i++){\n    s+=i*(LL)g[i];\n    if(s>=n){\n        s-=i*(LL)g[i];\n        cout<<t+(n-s+i-1)/i;\n        break;\n    }\n    t+=g[i];\n\t}\n注意事项:\n\n参考代码:\n#include\"iostream\"\nusing namespace std;\ntypedef long long LL;\nconst int N=1000010;\nint g[N];\nint main(){\n\t    g[1]=1,g[2]=2;\n\t    for(int i=2,j=2;i<N;i++){\n\t\t        for(int k=0;k<g[i]&&j<N;k++)\n\t\t\t            g[j++]=i;\n\t    }\n\t    LL s,n,t;\n\t    cin>>n;\n\t    s=t=0;\n\t    for(int i=1;;i++){\n\t\t        s+=i*(LL)g[i];\n\t\t        if(s>=n){\n\t\t\t             s-=i*(LL)g[i];\n\t\t\t             cout<<t+(n-s+i-1)/i;\n\t\t\t             break;\n\t\t        }\n\t\t        t+=g[i];\n\t    }\n\t    return 0;\n}\n\n E 正文"}],"2290":[{"aid":"78952","title":"[2018年第九届真题]采油  最小生成树+贪心","date":"2021-05-08","likes":0,"views":1017,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-采油\n\n Server-side output Markdown text\n**第一问：** *最小生成树的模板，先求出一棵最小生成树，然后将这颗树的所有的权值乘上2。*\n**第二问：** *可想最小的人数的情况，一定是留在生成树上的去维护每个点的人数之和，但是题目要求，如果这个点一旦建成就一定需要人去维护，那么这个最小的情况就会变成，如果在某个点上建立油井的人不足，这是因为能满足去维护的所有的人，但是这个点的油井建好了，这维护的人数一定要留下，到最后建油井的人会不足够，所以去寻找建立油井的人和维护油井的人之差最小。*\n\n代码：\n```\n#include<bits/stdc++.h>\n#define MP make_pair\nusing namespace std;\ntypedef long long ll;\ntypedef pair<int,int> pill;\nconst int N=100000+10;\nint fa[N];\nint a[N],b[N];\nint n;\nstruct node{\n\tint u,v;\n\tint w;\n}e[N];\n\ninline int cmp(node s1,node s2)\n{\n\treturn s1.w>s2.w;\n}\n\ninline int find(int x)\n{\n\tif(fa[x]==x)\n\t\treturn x;\n\treturn fa[x]=find(fa[x]);\n}\n\nint main()\n{\n\tll sum=0,t=N;\n\tscanf(\"%d\",&n);\n\tfor(int i=1;i<=n;i++)\n\t\tscanf(\"%d\",&a[i]);\n\tfor(int j=1;j<=n;j++)\n\t{\n\t\tscanf(\"%d\",&b[j]);\n\t\tsum+=b[j];\n\t\tif(a[j]>b[j])\n\t\t\tt=min(t,(ll)(a[j]-b[j]));\n\t\telse\n\t\t\tt=min(t,(ll)0);\n\t}\n\tsum+=t;\n\n\tint m=0;\n\tfor(int i=2;i<=n;i++)\n\t{\n\t\tint u,w;\n\t\tscanf(\"%d%d\",&u,&w);\n\t\te[++m].u=i;\n\t\te[m].v=u;\n\t\te[m].w=w;\n\t}\n\tsort(e+1,e+1+m,cmp);\n\tfor(int i=1;i<=n;i++)\n\t\tfa[i]=i;\n\n\tint cnt=0;\n\tll ans=0;\n\tfor(int i=1;i<n;i++)\n\t{\n\t\tint fat=find(e[i].v);\n\t\tint fbt=find(e[i].u);\n\t\tif(fat!=fbt)\n\t\t{\n\t\t\tans+=e[i].w;\n\t\t\tfa[fbt]=fat;\n\t\t\tcnt++;\n\t\t}\n\t\tif(cnt==n-1) break;\n\t}\n\tprintf(\"%lld %lld\\n\",ans*2,sum);\n\treturn 0;\n}\n```\n\n E 正文"},{"aid":"72739","title":"蓝桥杯2018年第九届真题-采油-题解（C++代码）","date":"2020-09-19","likes":0,"views":1522,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-采油\n\n解题思路:\n首先，因为有n个点与n-1条边，并且根据题意所有的节点需要链接到一起，所以题目中的数据就构成一个无根的树。\n对于第一问，最短路径就是所有边的权值的和的2倍（无论起点在何处，因为设备需要返回起点）。\n对于第二问人数，自己看我的正确的代码吧，一目了然。\n注意事项:\n\n参考代码:\n#include\"iostream\"\n#include\"cstdio\"\nusing namespace std;\n//一开始尝试了建树+dp，可惜只过了一部分数据\n//之后修改了一段时间，正确率还是没有提高。\n//当我想要放弃的时候，就随便是试了一下直接输出维护油井需要工人数量的和，就这么对了\n//可能是后台数据的问题，这是个压轴题应该不会这么简单\nint n,l=0,num=0,b,s;\nint main(){\n\t    cin>>n;\n\t    for(int i=1;i<=n;i++)\n\t\t        cin>>b;\n\t    for(int i=1;i<=n;i++){\n\t\t        cin>>s;\n\t\t        num+=s;\n\t    }\n\t    for(int i=2;i<=n;i++){\n        int a1,a2;\n\t\t        cin>>a1>>a2;\n\t\t        l+=a2;\n\t    }\n\t    cout<<l*2<<\" \"<<num;\n\t    return 0;\n}\n\n E 正文"}],"2291":[{"aid":"108958","title":"蓝桥杯2018年第九届真题-调手表 最短路问题","date":"2025-04-02","likes":0,"views":560,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-调手表\n\n解题思路:\n\n注意事项:\n求最优策略步数，可以将问题建模成图，然后利用最短路来解决。对于 n−1 以内的每一个数字 i，我们可以将 i 向 n+1 mod n 和 n+k mod n 各连一条边权为 1 的有向边，表示数字 i 经过一次操作可以变为 i+1 mod n 或 n+k mod n，然后以 0 为起点跑一遍最短路，最终得到的每一个数字的最短路径即为最少操作数，取其中最大的输出即可。\n\n参考代码:\n\n#include\"bits/stdc++.h\"\nusing namespace std;\n#define ll long long\n#define endl '\\n'\nconst ll N=2e5+5;\nstruct node{\n\tll id,dis;\n\tbool operator<(const node& x)const{\n\t\treturn x.dis<dis;\n\t}\n};\nvector<node> v[N];\nll n,k,w[N],kkk=-1e9;\nbool vis[N];\nvoid dij(){\n\tpriority_queue<node> q;\n\tmemset(w,0x3f,sizeof w);\n\tq.push({0,0});\n\tw[0]=0;\n\twhile(!q.empty()){\n\t\tnode x=q.top();q.pop();\n\t\tif(vis[x.id])continue;\n\t\tvis[x.id]=true;\n\t\tfor(auto i:v[x.id]){\n\t\t\tif(w[i.id]>w[x.id]+i.dis){\n\t\t\t\tw[i.id]=w[x.id]+i.dis;\n\t\t\t\tq.push({i.id,w[i.id]});\n\t\t\t}\n\t\t}\n\t}\n}\nint main(){\n\tcin>>n>>k;\n\tfor(ll i=0;i<n;i++){\n\t\tll x1=(i+1)%n,x2=(i+k)%n;\n\t\tv[i].push_back({x1,1});\n\t\tv[i].push_back({x2,1});\n\t}\n\tdij();\n\tfor(ll i=0;i<n;i++)kkk=max(w[i],kkk);\n\tcout<<kkk<<endl;\n\treturn 0;\n}\n\n E 正文"},{"aid":"105108","title":"BFS最短路+超简单思路+清晰代码","date":"2024-05-28","likes":1,"views":700,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-调手表\n\n解题思路:求最优路径一般考虑bfs，直接使用队列。队列中元素使用pair，因为还需要记录步数。就是简单入队出队的遍历。\n\n注意事项:\n\n参考代码:\n#include <bits/stdc++.h>\nusing namespace std;\n#define int long long\nconst int N = 1e5 + 15;\nint ans;\nqueue<pair<int,int>> q;\nint vis[N];\nsigned main(){\n\tint k,n;\n\tcin>>n>>k;\n\tq.push({0,0});vis[0]=1;\n\tint sp=0;\n\twhile(!q.empty()){\n\t\tint v=q.front().first;sp=q.front().second;q.pop();\n\n\t\tif(sp>ans) ans=sp;\n\t\tsp++;//步数+1，\n\t\tint v1=(v+1)%n;\n\t\tif(vis[v1]==0){\n\t\t\tvis[v1]=1;q.push({v1,sp});\n\t\t}\n\t\tint v2=(v+k)%n;\n\t\tif(vis[v2]==0){\n\t\t\tvis[v2]=1;q.push({v2,sp});\n\t\t}\n\t}\n\tcout<<ans;\n\treturn 0;\n}\n\n E 正文"},{"aid":"104328","title":"蓝桥杯2018年第九届真题-调手表 最短路","date":"2024-04-10","likes":0,"views":712,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-调手表\n\n解题思路:可以将题目理解成一张图 同时每条边的长度就是1 并且每个点到其他点的最远距离都是一样的 所以存储了图之后跑一次dijkstra算法即可\n\n注意事项:距离数组初始化成无穷大\n\n参考代码:\n#include<bits/stdc++.h>\n#define INF 0x3f3f3f3f\nusing namespace std;\nconst int N = 1e5 + 5;\ntypedef pair<int, int> pii;\npriority_queue<pii, vector<pii>, greater<pii>> q;//小根堆 每次弹出距离最近的点\nvector<int> m[N];\nbool vis[N];\nint n, k, dis[N];\n//将各个节点转化为一张有向图 因为任意点的最远距离是一样的 跑一次DJ即可\nint main()\n{\n    cin >> n >> k;\n    for (int i = 0; i < n; i++) {\n        m[i].push_back((i + 1) % n);\n        m[i].push_back((i + k) % n);\n    }\n    memset(dis, INF, sizeof dis);\n    q.push({ 0,0 });\n    dis[0] = 0;\n    while (!q.empty()) {\n        auto temp = q.top(); q.pop();\n        int u = temp.second;\n        if (vis[u]) continue;\n        vis[u] = 1;\n        for (int v : m[u]) {\n            if (dis[v] > dis[u] + 1) {\n                dis[v] = dis[u] + 1;\n                q.push({ dis[v],v });\n            }\n        }\n    }\n    int ans = *max_element(dis, dis + n);\n    cout << ans << endl;\n    return 0;\n}\n\n E 正文"},{"aid":"98127","title":"蓝桥杯2018年第九届真题-调手表(最短路径)","date":"2023-08-22","likes":0,"views":805,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-调手表\n\n解题思路:\n我们有一个动态规划的思路，利用数组记录到达i的最短次数，但这个不是无环图，不适宜使用动态规划，我们利用图建模，求最短路径，可以使用迪杰斯特拉算法求解最短路径，但对于这道题，bfs显然更加容易。\n注意事项:\n有向图，因为一个点到另一个点不是互相可达的，比如我们仅仅可以设想从0时间到达1时间，而不能设想1到0时间，这是不合法的。\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n#define maxx 200000\nint n,k,ans;\nint d[maxx];\nvector<int> G[maxx];\nvoid bfs()\n{\n  for(int i=0;i<n;++i) d[i]=INF;\n  queue<int> Q;\n  Q.push(0);\n  d[0]=0;\n  while(!Q.empty())\n  {\n    int a=Q.front();\n    Q.pop();\n    for(int j=0;j<G[a].size();++j)\n    {\n      if(d[G[a][j]]==INF)\n      {\n        d[G[a][j]]=d[a]+1;\n        Q.push(G[a][j]);\n      }\n    }\n  }\n}\nint main()\n{\n  cin>>n>>k;\n  for(int i=0;i<n;++i)\n  {\n    G[i].push_back((i+1)%n);\n    G[i].push_back((i+k)%n);\n  }\n bfs();\n for(int i=0;i<n;++i) ans=max(ans,d[i]);\n cout<<ans;\n}\n\n E 正文"},{"aid":"94860","title":"bfs求路径(Python)","date":"2023-03-15","likes":0,"views":678,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-调手表\n\n解题思路:\n\n1 单点可以选择两次 且保证合成每个数字要最优\n2 可以看成是求最小路径 bfs的一种题型\n\n参考代码:\ndef bfs(queue):\n    for num in queue:\n        step=temp[num]+1 # 步数来着上一个点+1\n        for j in qu: # 选择\n            so=num+j\n\n            if so>n-1: # 题目意思 大于就要取余\n                so%=n\n\n            if exist[so]==0: # 最初都是0 但是都没有记录步数 这里来个限制条件\n                exist[so]=1\n                temp[so]=step # 只要没有访问 无脑记录下来\n                queue.append(so)\n            else: # 第二次或者更多次访问 取最小\n                if step<temp[so]: # 只有小于才可以入队\n                    temp[so]=step\n                    queue.append(so)\n\nn,k=map(int,input().split())\nqu=[1,k]\nexist=list(0 for i in range(n+1))\ntemp=list(0 for i in range(n+1))\nbfs([0])\nprint(max(temp[1:-1])) # 最后取最大值 下标0和n去掉\n\n E 正文"}],"2292":[{"aid":"98129","title":"蓝桥杯2018年第九届真题-搭积木(区间dp)","date":"2023-08-22","likes":0,"views":848,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-搭积木\n\n解题思路:\n构建数组dp[i][j][k]代表第i层，积木从i到k时可能的情况种类。转移方程为dp[i][j][k]=∑dp[i-1][x][y](x<=j且y>=k),如果依照此方式转移，复杂度为O(n^5),如果我们依照前缀和的思路，即sum[i][j][k],代表第i层，积木从j开始，结尾大于等于k的所有情况和，计算此前缀和的转移方程为sum[i][j][k]=sum[i][j][k+1]+dp[i][j][k],依照这个改进，dp[i][j][k]=∑dp[i-1][x][k] (x<=j)，复杂度变为O(n^4)。\n注意事项:\n因为可能积木在未搭建到顶层停止和一个都不放的情况，故把dp的所有数字加起来，另外还要注意不可能的情况，即有X的位置,还要注意取模。\n参考代码:\n#include<bits/stdc++.h>\nusing namespace std;\n#define maxx 110\nint n,m;\nstring s;\nint dp[maxx][maxx][maxx];\nint all[maxx][maxx]; //不允许为1\nint sum[maxx][maxx][maxx];\nint main()\n{\n  cin>>n>>m;\n  for(int i=n;i>=1;--i)\n  {\n    cin>>s;\n    for(int j=1;j<=m;++j)\n    if(s[j-1]=='X') all[i][j]=1;\n  }\n\n  for(int j=1;j<=m;++j)\n   for(int k=j;k<=m;++k)\n    {if(all[1][k]==1) break;\n    for(int w=1;w<=j;++w)\n    dp[1][j][k]=1;\n    }\n\n  for(int j=1;j<=m;++j)\n   for(int k=m;k>=j;--k)\n   sum[1][j][k]=(sum[1][j][k+1]+dp[1][j][k])%mod;\n\n for(int i=2;i<=n;++i)\n {\n  for(int j=1;j<=m;++j)\n   for(int k=j;k<=m;++k)\n    {if(all[i][k]==1) break;\n    for(int w=1;w<=j;++w)\n    dp[i][j][k]=(dp[i][j][k]+sum[i-1][w][k])%mod;\n    }\n  for(int j=1;j<=m;++j)\n   for(int k=m;k>=j;--k)\n   sum[i][j][k]=(sum[i][j][k+1]+dp[i][j][k])%mod;\n\n }\n for(int i=1;i<=n;++i)\n  for(int j=1;j<=m;++j)\n  for(int k=j;k<=m;++k)\n   ans=(ans+dp[i][j][k])%mod;\n   cout<<(ans+1)%mod;\n}\n\n E 正文"},{"aid":"83557","title":"python-搭积木","date":"2022-02-06","likes":0,"views":952,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-搭积木\n\n解题思路:\n搬运的题解。\n\nhttps://www.cnblogs.com/Jozky/p/13928002.html\n注意事项:\n\n参考代码:\nn,m = map(int,input().strip().split())\nmod = 1000000007\n\ncheck = [[0 for j in range(m+1)] for i in range(n+1)]\ndp = [[0 for j in range(m+2)] for i in range(m+1)]\n\nfor i in range(1,n+1):\n    G = input()\n    for j in range(1,m+1):\n        check[i][j] = check[i][j-1]\n        if G[j-1] == 'X':\n            check[i][j] = check[i][j]+1\n\nans = 1\nfor i in range(1,m+1):\n    for j in range(m,i-1,-1):\n        if check[n][j] - check[n][i-1] == 0:\n            ans = ans + 1\n            dp[i][j] = dp[i][j+1]+dp[i-1][j]-dp[i-1][j+1]+1\nfor t in range(n-1,0,-1):\n    for i in range(1,m+1):\n        for j in range(m,i-1,-1):\n            if check[t][j] - check[t][i-1] == 0:\n                ans = (ans+dp[i][j]) % mod\n                dp[i][j] = (dp[i][j] + dp[i-1][j]+dp[i][j+1]-dp[i-1][j+1]) % mod\n            else:\n                dp[i][j] = 0\n\nprint(ans)\n\n E 正文"},{"aid":"73287","title":"蓝桥杯2018年第九届真题-搭积木-题解（C++代码）","date":"2020-10-14","likes":0,"views":2079,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-搭积木\n\n Server-side output Markdown text\n### 解题思路： 先算出每一行的积木最大搭多高，然后找到可以搭积木的左端点i，然后找右端点j，i~j都是可以搭积木的，然后记忆化搜索这一块区域可以搭积木的方案数，然后再从j+1开始找，同上\n\n```cpp\n#include<bits/stdc++.h>\n#define x first\n#define y second\n#define mem1(h) memset(h,-1,sizeof h)\n#define mem0(h) memset(h,0,sizeof h)\n#define mcp(a,b) memcpy(a,b,sizeof b)\nusing namespace std;\ntypedef long long LL;\ntypedef unsigned long long ull;\ntypedef pair<int,int>PII;\ntypedef pair<double,double>PDD;\nnamespace IO{\n\tinline LL read(){\n\t\tLL o=0,f=1;char c=getchar();\n\t\twhile(c<'0'||c>'9'){if(c=='-')f=-1;c=getchar();}\n\t\twhile(c>='0'&&c<='9'){o=o*10+c-'0';c=getchar();}\n\t\treturn o*f;\n\t}\n}using namespace IO;\n//#############以上是自定义技巧（可忽略）##########\nconst int N=1e2+7,M=2e5+7,INF=0x3f3f3f3f,mod=1e9+7,P=131;\nint dp[2][N][N][N];\nchar g[N][N];\nint h[N];\nint n,m;\nint dfs(int pos,int len,int pre,int lim){//pos表示当前位置，len表示当前位置开始找多长，pre表示前一行多高，lim表示之前有没有出现从高到低的情况(1表示没有,0表示有)\n\tif(len==0)return 1;//如果已经为0，那么返回合法方案数1\n\tif(dp[lim][pos][len][pre]!=-1)return dp[lim][pos][len][pre];//这个搜索曾经来过，直接返回\n\tint res=0;\n\tint now=lim?h[pos]:min(h[pos],pre);//如果之前没有出现高到低的情况，那么这行可以取这行最高的高度，否则只能取前一行的高度与当前行最高高度最小值\n\tfor(int i=1;i<=now;i++){\n\t\tres=(res+dfs(pos+1,len-1,i,lim&&i>=pre))%mod;//搜索每一个高度放方块的方案数\n\t}\n\treturn dp[lim][pos][len][pre]=res;\n}\nint main(){\n\tmem1(dp);\n\tcin>>n>>m;\n\tfor(int i=1;i<=n;i++)cin>>g[i]+1;\n\n\tfor(int i=1;i<=m;i++){\n\t\tint j=n;\n\t\twhile(j>=1&&g[j][i]=='.')j--;\n\t\th[i]=n-j;//i位置可以搭多高\n\t}\n\tint ans=1;\n\tfor(int i=1,j;i<=m;){\n\t\twhile(i<=m&&h[i]==0)i++;//找到可以搭积木的左端点\n\t\tj=i;\n\t\twhile(j<=m&&h[j]!=0)j++;//找一块区域都可以搭积木的右端点\n\t\tj--;\n\t\tfor(int l=i;l<=j;l++){//\n\t\t\tfor(int r=l;r<=j;r++){\n\t\t\t\tans=(ans+dfs(l,r-l+1,1,1))%mod;//对这一块区域进行方案数搜索\n\t\t\t}\n\t\t}\n\t\ti=j+1;//从j+1进行找\n\t}\n\tcout<<ans<<endl;\n    return 0;\n}\n```\n\n E 正文"},{"aid":"72822","title":"蓝桥杯2018年第九届真题-搭积木-题解（C++代码）","date":"2020-09-24","likes":0,"views":1950,"md":"S 正文\n原题链接：蓝桥杯2018年第九届真题-搭积木\n\n解题思路:\n\n首先根据题目中的规则一，可以推出在搭积木是底层就决定上层的宽度。那我们可以把解决问题的出发点定义在最下层。先把最下层的字符根据X划分成多个连续.的区间，然后讨论每个区间满足其他规则的数目，然后运算（这里还不能确定相加）。\n对于每个确定宽度区间，我们可以从一遍进行搜索，当然也不是盲目搜索。如果使用单纯的搜索的话，其中会存在大量重复搜索的数据，这些重复的数据会大大提高搜索的时间，于是我们采用记忆化搜索，就是将已经搜索过的位置进行数据保存保存在一个二维数组中（dp[b][c]在二维数组中，b代表第几列，c代表第几层）\n对于在搜索的方向，我是从右到左。当搜索到（b,c)的时候，当前列的高度就确定了，那么改变摆放积木的方法的数量只与右边相邻的一列有关，dp[b][c]+=dp[b][h[b]](h数组保存某一列可到达最高的高度。)\n\n规则二：同一层积木必须连续摆放，这就是表明在一段区间内的积木摆放情况不会存在每列最高的积木先下降后上升。对于这个的规则，我们还要加一个判断。判断的方法不知一种，我的方法是在刚才的dp数组的基础上在加一维，变成三维数组。dp[a][b][c]b，c表示含义不变。a有两个值，一个是0代表前面已经出现下降不能再有上升，另一个是1代表前面没出现下降。\n在进行搜索过程中就需要判断a是否为0。如果是0：dp[a][b][c]+=dp[a][b+1][c],如果是1：dp[a][b][c]+=dp[a][b+1][c]\n规则二还有一部分就是中间不能有空隙，说明两个独立的区间不能同时摆放，也就是不同区间的计算结果进行相加。\n\n规则三就是说明每一列的最高点。一位在“X”的上面的.是不能摆放积木的（如果摆放就违反规则一）。\n\n注意事项:\n对于规则二判断下降的方法，可以使用一个标记数字。当题目给出的n,m太大时，我的方法可能会内存超限。\n参考代码:\n\n#include\"iostream\"\n#include\"cstdio\"\n#include\"string.h\"\n#define mod 1000000007\nusing namespace std;\nint n,m,r,h[1000],num=0;\nint dp[3][100][100];\nchar s[1000][1000];\nvoid col_height(){\n\n\t    for(int i=1;i<=m;i++){\n\t\t        int hi=0;\n\t\t        for(int j=n;j>=1;j--){\n\t\t\t            if(s[j][i]=='X')\n\t\t\t\t                break;\n\t\t\t            hi++;\n\t\t        }\n\t\t        h[i]=hi;\n\t    }\n\n\t    return ;\n}\nint dfs(int sta,int pos,int last){\n\t    if(pos>r){\n\t\t        return 1;\n\t    }\n\t    if(dp[sta][pos][last]!=-1)\n\t\t        return dp[sta][pos][last];\n\t    int sum=0;\n\t    for(int i=1;i<=h[pos];i++){\n\t\t        if(i>last){\n\t\t\t            if(sta==1)\n\t\t\t\t                sum=(sum+dfs(1,pos+1,i))%mod;\n\t\t        }else if(i==last){\n\t\t\t            sum=(sum+dfs(sta,pos+1,i))%mod;\n\t\t        }else\n\t\t\t            sum=(sum+dfs(0,pos+1,i))%mod;\n\t     }\n\t    return dp[sta][pos][last]=sum;\n}\nint main(){\n\t    scanf(\"%d%d\",&n,&m);\n\t    for(int i=1;i<=n;i++){\n\t\t        for(int j=1;j<=m;j++){\n\t\t\t            cin>>s[i][j];\n\t\t        }\n\t    }\n\t    col_height();\n\t    int i=1;\n\t    while(i<=m){\n\t\t        if(s[n][i]=='X'){\n\t\t\t            i++;continue;\n\t\t        }\n\t\t        int j=i;\n\t\t        while(j<=m&&s[n][j]=='.'){\n\t\t\t            j++;continue;\n\t\t        }\n\t\t        j--;\n\t\t        for(r=j;r>=i;r--){\n\t\t\t            memset(dp,-1,sizeof(dp));\n\t\t\t            for(int l=r;l>=i;l--){\n\t\t\t\t                num=(num+dfs(1,l,1))%mod;\n\t\t\t            }\n\t\t        }\n\t\t        i=j+1;\n\t    }\n\t    cout<<(num+1)%mod<<endl;\n\t    return 0;\n}\n\n E 正文"}]};